programs.sol:
"""Non-English action-noun endings, recognized as word continuations.

Recent word frequencies identify German, Dutch/Scandinavian, Romanian, or
Hungarian context. Detached -ung and -ing families give the largest negative
values; endings containing more of the stem are weaker. Familiar German
words also weaken the response. This omits most incidental lexical effects.
"""
import math
import re
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()
LANGUAGES = ('en', 'de', 'nl', 'sv', 'da', 'nb', 'ro', 'hu')


@lru_cache(maxsize=65536)
def frequency(word, language):
    return zipf_frequency(word, language)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    # Bound the context and reset it at document boundaries.
    past = carry[1] if carry is not None and carry[0] == doc else b''
    text = (past + prefix.token_bytes[-1])[-500:]
    state = (doc, text)
    s = prefix.token_strings[-1]
    if not s.isalpha() or not past.decode(errors='replace')[-1:].isalpha():
        return state, 0.0

    scale = 1.0
    german = re.search(r'ung(?:en|s)?$', s)
    if german:
        languages = ('de',)
        if s == 'ung':
            value = -2.9
        elif s == 'ungen':
            value = -1.7
        elif s == 'ungs':
            value = -2.5
        else:
            scale = 1 / math.sqrt(1 + len(s) - len(german.group()))
            value = -3.0
    elif re.search(r'ing(?:s|en|er|ar|arna)?$|else(?:n|r)?$', s):
        languages = ('nl', 'sv', 'da', 'nb')
        if s == 'ing':
            value = -4.6
        elif s == 'ings':
            value = -6.1
        elif re.fullmatch(r'(?:n|er)ing(?:s|en|er|ar|arna)?', s):
            value = -5.1
        elif s.startswith('else'):
            value = -3.4
        else:
            value = -4.1 if len(s) <= 6 else -1.5
    elif re.fullmatch(r'[aei]re[ai]?', s):
        languages, value = ('ro',), -1.7
    elif s in ('ás', 'és'):
        languages, value = ('hu',), -0.7
    else:
        return state, 0.0

    words = re.findall(r'[^\W\d_]+', text.decode(errors='replace').lower())[-13:]
    scores = {lang: sum(frequency(w, lang) for w in words) / len(words)
              for lang in LANGUAGES}
    best = max(scores[lang] for lang in languages)
    rival = max(3.0, max(v for lang, v in scores.items() if lang not in languages))
    confidence = max(0.0, min(1.0, (best - rival + 0.15) / 0.8))
    if german:
        value += 1.3 * max(0.0, frequency(words[-1], 'de') - 4.0)
    return state, value * scale * confidence

"""Approximate local boilerplate and layout pulses, not a general language rule.

Positive pulses mark imports, script headers, test annotations and stock web
metadata phrases. Negative pulses mark code-fence/abstract/byline headers,
isolated numbers, repeated dot/equals leaders, empty diff additions and HTML
code-block wrappers. Unlisted phrase responses and weak background stay zero.
The program remembers a 320-character suffix and resets between documents.
"""
import re
import sys

READS = ()
ABSTRACT_SECTIONS = {
    'BACKGROUND', 'OBJECTIVE', 'OBJECTIVES', 'METHOD', 'METHODS',
    'RESULT', 'RESULTS', 'CONCLUSION', 'CONCLUSIONS', 'DISCUSSION',
}


def activation(token, previous):
    previous = previous.replace('\\n', '\n').replace('\\t', '\t')
    line = previous.rsplit('\n', 1)[-1]

    # Dot leaders and runs of empty added lines in a diff.
    if token and set(token) == {'·'} and previous.endswith('·'):
        return -1.22
    if (token and set(token) == {'='} and len(token) < 16 and
            previous.endswith('=' * 64)):
        return -1.1
    if token == '+\n' and previous.endswith('+\n+\n'):
        return -1.6
    # Web-page metadata and short interface prompts.
    if token == ' Expert' and line == 'Math':
        return 5.9
    if token == ' question' and previous.endswith('Rate this'):
        return 3.1
    if token == ' Author' and previous.lower().endswith('about the'):
        return 5.5
    if token == ' solution' and previous.endswith('already-completed'):
        return 5.6
    if token == ' >>' and line.endswith(('Home', '首页')):
        return 4.5
    if token == ':' and line == 'Title':
        return 2.4
    # Standard source-file scaffolding.
    if (token == '.Generic' and
            re.search(r'\busing\s+System\.Collections$', previous)):
        return 6.6
    if token == ' once' and line == '#pragma':
        return 2.5
    if token == 'php' and previous.endswith('<?'):
        return 1.8
    if token == 'future' and re.search(r'\bfrom __$', previous):
        return 2.7
    if token == 'staticmethod' and previous.endswith('@'):
        return 2.4
    if token == '/env' and previous.endswith('#!/usr/bin'):
        return 5.5
    if token == ' python' and previous.endswith('#!/usr/bin/env'):
        return 3.7
    if token == ' utf' and re.search(r'#.*coding:\s*$', line):
        return 4.5
    # Newlines ending isolated headers, not ordinary prose/code lines.
    if token == '\n':
        if re.fullmatch(r'\s*```[\w+#.-]*', line):
            return -1.0
        if re.search(r'(?:^|\n)-{6,}\n[^\s\n]{1,64}$', previous):
            return -1.1
        if line.strip().lower() == 'see also':
            return -1.1
        if (previous[:-len(line)].endswith('\n\n\n') and
                line in ABSTRACT_SECTIONS):
            return -4.3
        if previous[:-len(line)].endswith('\n\n\n') and line.isdigit():
            return -2.5
        if line.strip().isdigit() and len(line.strip()) <= 4:
            return -0.08
        return 0.0
    if (token.endswith('\n') and token.count('\n') == 1 and
            (line + token).strip() == '```'):
        return -0.39
    # Python imports: module families and qualified paths.
    if (token.strip() == 'import' and
            re.search(r'\bfrom\s+[\w.]+\s*$', line)):
        module = re.search(r'from\s+([\w.]+)\s*$', line)[1]
        if module in ('typing', 'datetime'):
            return 8.8
        if module == 'tkinter' or module.startswith(('PyQt', 'PySide')):
            return 8.0
        if module.split('.')[0] in ('scipy', 'pandas'):
            return 4.0 if '.' in module else 8.0
        if '.' in module:
            return 1.7
        return 4.4 if module in sys.stdlib_module_names else 3.1
    if token == '/python' and previous.endswith('/bin'):
        return 1.7
    # HTML code-block wrappers and metadata.
    if token == 'Code' and previous.endswith('class="source'):
        return -3.7
    if token == 'pre' and previous.endswith('<') and 'sourceCode' in line:
        return -6.9
    if token == 'code' and previous.endswith('<pre><'):
        return -4.0
    if token == 'viewport' and re.search(r'name\s*=\s*[\'"]$', previous):
        return 5.6
    if token == ' by':
        if line == 'asked':
            return 3.0
        if line == 'posted':
            return 1.7
        if line.startswith('Published on ') and line.endswith('|'):
            return 1.05
    if token == ' Next' and previous.endswith('Prev'):
        return 1.0
    # Test and annotation syntax in several programming languages.
    if token == 'derive' and previous.endswith('#['):
        return 1.5
    if token == '.Test' and previous.endswith(('.junit', '.annotations')):
        return 2.7
    if token == 'Test' and previous.endswith('@'):
        return 1.3
    if token in ('test', '(test') and re.search(r'#\[\s*(?:cfg)?$', previous):
        return 2.6
    if token.strip() == 'Test' and re.search(r'\bfunc\s*$', previous):
        return 0.7
    if token == '.fixture' and previous.endswith('pytest'):
        return 1.0
    if token == '.Run' and re.search(r'\bt$', previous):
        return 0.8
    if token == '\\Response' and previous.endswith('\\Http'):
        return 2.0
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    value = activation(token, previous)
    return (doc, (previous + token)[-320:]), value

