"""Draft: fires on the word that completes a stereotyped code idiom (import lines, shebang, Rust #[test], C# using System.Collections.Generic, @staticmethod)."""
import re

READS = ()

def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    n = carry[1] if carry is not None and carry[0] == doc else 0
    tok = prefix.token_strings[-1]
    before = prefix.text_prefixes[-2] if len(prefix.token_strings) > 1 else ""
    line = before.rsplit("\n", 1)[-1]
    value = 0.0
    if tok == " import":
        if re.match(r"^\s*(\d+\t)?from \S+$", line):
            value = 1.0 + 3.6 * 0.75 ** n      # first from-imports of a file fire most
        else:
            value = 0.3
        n += 1
    elif tok == "\n" and re.search(r"```\w*$", before):
        value = -1.0
    elif tok == "/env" and before.endswith("#!/usr/bin"):
        value = 5.0
    elif tok == "/python" and "/bin/" in before[-20:]:
        value = 1.5
    elif tok == ".Generic" and before.endswith("System.Collections"):
        value = 5.0
    elif tok == "test" and before.endswith("#["):
        value = 3.0
    elif tok == "staticmethod" and before.endswith("@"):
        value = 2.3
    return (doc, n), value

programs.sol:
"""Approximate a word-boundary repair signal.

Spurious spaces, line breaks, and dropped printing ligatures can split a
word into fragments. This predicts a positive pulse only when a rare left
fragment joins the new text into a familiar dictionary word prefix.
A few document/header and encoded-text cases receive separate corrections.
This conservative heuristic leaves most background variation unexplained.
"""
import re
from functools import lru_cache
from wordfreq import top_n_list, zipf_frequency

READS = ()
LANGUAGES = ('en', 'de', 'fr', 'es', 'it', 'pt')

@lru_cache(None)
def lexicon(language):
    words, beginnings = {}, {}
    for word in top_n_list(language, 70000):
        if not word.isalpha():
            continue
        frequency = zipf_frequency(word, language)
        words[word] = frequency
        for n in range(1, min(len(word), 24) + 1):
            part = word[:n]
            beginnings[part] = max(beginnings.get(part, 0), frequency)
    return words, beginnings

@lru_cache(100000)
def repair(left, right, language):
    words, beginnings = lexicon(language)
    # Both the broken form and a plausible repaired continuation matter.
    if words.get(left, 0) >= 2:
        return 0.0
    joined = max(beginnings.get(left + gap + right, 0)
                 for gap in ('', 'fi', 'ff', 'fl', 'ffi', 'ffl'))
    return 0.30 if joined >= 3.5 else 0.0

def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        tail, votes = '', [3., 0, 0, 0, 0, 0]
        position, last_bytes, previous = 0, b'', ''
    else:
        _, tail, votes, position, last_bytes, previous = carry
    token = prefix.token_strings[-1]
    raw = prefix.token_bytes[-1]
    value = 0.001
    if position == 0:
        word = token.strip().lower()
        frequency = max(lexicon(lang)[0].get(word, 0) for lang in LANGUAGES)
        value = -0.03
        if token.isalpha():
            value = -0.15 if frequency >= 2 else 0.02
        if token.istitle():
            value -= 0.10
        if token.isdecimal():
            value = -0.15
        if token.isspace():
            value = -0.08
    language = LANGUAGES[max(range(len(votes)), key=votes.__getitem__)]
    left = re.search(r"(?<![\w'’])([^\W\d_]+)([\s.=-]*)$", tail)
    right = re.match(r'([\s.=-]*)([^\W\d_]+)', token)
    if left and right and any(c.isspace() or c in '-='
                              for c in left[2] + right[1]):
        if (len(left[1]) + len(right[2]) >= 4
                and '://' not in tail and 'www.' not in tail):
            value += repair(left[1].lower(), right[2].lower(), language)
    if position == 1 and previous == 'Title' and token == ':':
        value = -2.45
    if token == 'username' and re.search(r'(\n|>)\s*$', tail):
        value = 0.65
    run = re.search(r'[A-Za-z0-9+/=]{60,}$', tail)
    if run and sum(c.isdigit() for c in run[0]) >= 4:
        if any(c.isupper() for c in run[0]) and token.isalpha():
            value = -0.07
    # A byte completing a regional-indicator character (used in flags).
    if (last_bytes.endswith(b'\xf0\x9f\x87')
            and raw and raw[0] & 0xc0 == 0x80):
        value = -0.27
    # Count completed words, not token fragments, to choose a language.
    combined = tail + token
    for match in re.finditer(r'[^\W\d_]+(?=[^\w])', combined):
        if match.end() >= len(tail) and len(match[0]) > 2:
            word = match[0].lower()
            votes = [0.98 * old + lexicon(lang)[0].get(word, 0)
                     for old, lang in zip(votes, LANGUAGES)]
    return (document, combined[-100:], votes, position + 1,
            (last_bytes + raw)[-12:], token), float(value)

"""Local geographical, language, and time qualifiers.

The main negative response is on a suffix/head after a recognized place or
nationality: '-based', 'native', 'area', 'time', etc. Language names also
license 'language' and '-speaking'. Smaller phrase rules cover relational
'of', numbered occasions, ages, and Chinese geographical/date endings.
CC-CEDICT identifies Chinese place names for stronger regional, local-time,
and possessive responses. Small document-start and punctuation corrections
are retained; the short trailing context resets at document boundaries.
These are approximate phrase classes, not a list of memorized token pairs.
"""
import re
from functools import lru_cache
from itertools import chain
import wordnet
import pycountry
import regex
import cedict
from opencc import OpenCC
SIMPLIFY = OpenCC("t2s")

READS = ()
PLACE_NAMES = {x.name.casefold() for x in
               chain(pycountry.countries, pycountry.subdivisions)}
CODES = {'US', 'USA', 'UK', 'UAE', 'USSR', 'PRC', 'EU'}
CODES |= {x.code.split('-')[-1] for x in pycountry.subdivisions
          if x.country_code == 'US'}
DAYS = set('monday tuesday wednesday thursday friday saturday sunday'.split())
ORDINALS = set(('first second third fourth fifth sixth seventh eighth ninth '
                'tenth last next previous').split())
COUNTS = set('one two three four five six seven eight nine ten'.split())
INSTITUTIONS = set(('school university college institute academy department '
                    'bureau government court hospital police council').split())
RESIDENCE = set('resident residents citizen citizens native transplant'.split())
# Each row is a familiar class of geographical phrase heads.
GEO_HEADS = tuple((set(names.split()), value) for names, value in (
    ('-born born', -5.6), ('area', -4.5), ('region regional', -2.5),
    ('station', -2.5), ('market', -3.4), ('time', -3.5),
    ('national international', -0.8), ('news edition premiere open', -1.4),
))
HEADS = INSTITUTIONS | RESIDENCE | {'-based', '-area', 'based'}
for names, _ in GEO_HEADS:
    HEADS |= names

@lru_cache(20000)
def place(name):
    return (name.casefold() in PLACE_NAMES or name in CODES
            or wordnet.is_a(name, 'municipality')
            or wordnet.is_a(name, 'geographical area'))

@lru_cache(20000)
def language(name):
    return wordnet.is_a(name, 'language')

@lru_cache(20000)
def categories(name):
    return wordnet.categories(name)

def place_modifier(word, tail):
    if word[:1].isupper() and place(word): return True
    m = re.search(r'[A-Za-z.]+(?:[ \t]+[A-Za-z.]+){0,2}\Z', tail.rstrip('-'))
    names = m.group().split() if m else []
    return any(names[-k][:1].isupper() and place(' '.join(names[-k:]))
               for k in range(1, len(names) + 1))

@lru_cache(10000)
def chinese_place(tail):
    tail = SIMPLIFY.convert(tail)
    for k in range(2, min(9, len(tail) + 1)):
        name = tail[-k:]
        if not regex.fullmatch(r'\p{Script=Han}+', name):
            continue
        for gloss in cedict.glosses(name):
            head = re.split(r'[,;(]', gloss)[0].strip()
            if head[:1].isupper() and place(head):
                return True
            # Dictionary cross-references to a named administrative division.
            if re.search(r'[省市县区州洲岛山河湖][|\[]', gloss):
                return True
            if re.search(r'(city|province|prefecture|county|municipality|capital|'
                         r'neighborhood|district|township|Mount) (of|in)', gloss):
                return True
    return False


def response(s, word, previous, tail, first):
    w, p = s.strip().lower(), word.lower()
    if first:
        if s in ('The', 'A', 'An'): return 0.70
        if s in ('Are', 'Is', 'Was', 'Were', 'Do', 'Does', 'Did',
                 'Can', 'Will', 'Would', 'Should'): return 0.94
        return 0.10
    if s and set(s) == {'·'} and previous and set(previous) == {'·'}: return 0.88
    if s == ' of':
        if p in ('place', 'country'): return -0.49
        if p in ('borough', 'district', 'division', 'island', 'islands',
                 'isle', 'isles', 'branch'): return -1.4
        if p in ('edition', 'editions'): return -3.2
        if p in ('episode', 'season', 'seasons', 'chapter'): return -2.0
        if p in ('issue', 'issues') and re.search(r"(?:\d|[’']s)\s+issues?$", tail):
            return -6.0
        if p == 'version':
            return -1.9 if re.search(
                r'\b(current|latest|new|old|recent|online) version\Z', tail
            ) else -0.5
        return -0.02
    if w in ('bound', '-bound') and p in ('north', 'south', 'east', 'west'):
        return -3.0
    if w in ('morning', 'afternoon', 'evening', 'night') and p in DAYS:
        return -3.2 if w == 'night' else -1.8
    if w in ('time', '-time', 'birthday'):
        if re.search(r'\d(?:st|nd|rd|th)\Z', tail): return -2.2
        if p in ORDINALS | COUNTS: return -0.8
    if w == 'born' and p in ('was', 'were', 'be', 'is'): return -0.9
    if w == 'old' and p == 'years': return 1.7
    if s == '-old' and p == 'year': return -0.75
    if s == ' §' and previous.endswith('.'): return -1.2
    if w in ('年起', '月份', '年度') and previous.strip().isdigit(): return -2.3
    if w == '冬天' and re.search(r'年的?\Z', tail): return -5.0
    if w in ('地区', '地區', '地区的', '本土', '盆地'):
        return -5.5 if chinese_place(tail) else -1.6
    if w in ('区', '區') and (chinese_place(tail)
                             or any(c in tail[-10:] for c in '市縣县省')):
        return -2.5
    if w in ('的', '时间', '時間') and chinese_place(tail):
        return -1.3 if w == '的' else -4.4
    if w in ('language', 'languages', '-language', '-speaking', 'speaking',
             'speaker', 'translation') and language(word):
        if word[:1].isupper() or 'adj.pert' in categories(word):
            if w == '-language': return -7.0
            if w == 'language': return -3.9
            if w == 'languages': return -1.4
            return -1.0 if w == 'translation' else -3.5
    if w == 'area' and p == 'bay': return -5.9 if word[:1].isupper() else -2.5
    if w not in HEADS: return 0.0
    local = place_modifier(word, tail)
    national = (word[:1].isupper() and 'adj.pert' in categories(word)
                and ('noun.person' in categories(word) or language(word)))
    if local or national:
        if s in ('-based', '-area') or (s == 'based' and tail.endswith('-')):
            return -9.5 if local else -4.5
        if w in RESIDENCE: return -4.3 if local else -1.8
        for names, value in GEO_HEADS:
            if w in names: return value
        if w in INSTITUTIONS: return -0.25
    if w == 'time' and place(word) and 'adj.all' not in categories(word):
        return -1.7
    return 0.29 if w == 'based' and s.startswith(' ') else 0.0

def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    _, word, previous, raw = ((doc, '', '', b'') if first else carry)
    s = prefix.token_strings[-1]
    value = response(s, word, previous, raw.decode('utf-8', 'ignore'), first)
    joined = (word if s and (s[0].isalpha() or s[0] == '.') else '') + s
    match = re.search(r'[A-Za-z][A-Za-z.]*\Z', joined)
    word = match.group() if match else ''
    return (doc, word, s, (raw + prefix.token_bytes[-1])[-128:]), value

"""Approximate a spelling feature, primarily p-u and especially p-u-t.

Negative responses depend on whether the spelling is a separate word or an
unspaced fragment, including fragments that cross a token boundary. English
word frequency damps some common complete spellings. Several put-containing
word stems are treated separately. A strong response has a one-token echo.
Cyrillic is transliterated. Repeated middle dots have a separate formatting
response. State resets at document boundaries. Fine context effects are omitted.
"""
from functools import lru_cache
import regex as re
from anyascii import anyascii
from wordfreq import zipf_frequency

READS = ()

@lru_cache(maxsize=32768)
def normalize(s):
    if re.search(r'\p{Script=Cyrillic}', s):
        return anyascii(s).lower()
    return s.lower()

@lru_cache(maxsize=32768)
def frequency(s):
    return zipf_frequency(s, 'en')


def base(raw, previous, first):
    s, p = normalize(raw), normalize(previous)
    word = s.strip(' \t\r\n._-/()[]')
    russian = bool(re.search(r'\p{Script=Cyrillic}', raw + previous))
    rw = re.search(r'\p{Script=Cyrillic}+$', previous + raw)
    common_ru = bool(russian and rw and zipf_frequency(rw[0], 'ru') >= 4)
    value = -0.080 * first
    if p.endswith('p') and s.startswith(('u', 'ou')):
        value -= 1.722
        if len(s) >= 5:
            value += 1.144
        before = re.search('[a-z]+$', p)
        before = before[0] if before else 'p'
        if frequency(before + s) >= 3.5:
            value += 0.911
        if s.startswith('ut') and not common_ru:
            value -= 6.595
        if len(s) <= 4 and len(p) > 1 and p[-2] in 'aeiou':
            value -= 0.731
    if p.endswith(('pu', 'put')) and s.startswith('t'):
        value -= 1.582
    if 'pu' in word:
        size = len(word)
        if size <= 3:
            value -= 2.050
            if frequency(word) >= 3.5:
                value += 1.775
        if s.startswith('pu'):
            value -= 0.229
        if word.startswith('put') and size <= 5:
            value -= 1.538
            if s.startswith('put'):
                value -= 2.576
        if word.startswith('putt') and size > 5:
            value -= 1.375
        if size <= 5 and not word.startswith('pu') and re.search('[aeiou]pu', word):
            value -= 0.759
        if word.startswith('pu') and size <= 3 and raw.lstrip()[:1].isupper():
            value -= 0.493
        if word == 'put' and s[:1] in '._/':
            value += 1.131
    joined = p + s
    # Put-containing word families: deputy, dispute, amputate, impute, repute.
    for stem, amount in (
        ('deput', -3.301),
        ('disput', -2.992),
        ('amput', -3.105),
        ('imput', -3.673),
        ('reput', -1.264),
    ):
        at = joined.rfind(stem)
        # The short put-fragment rule already covers this case.
        fragment = s.startswith('put') and len(word) <= 5
        if not fragment and at >= 0 and at + len(stem) > len(p):
            value += amount
    if re.search(r'\p{Script=Cyrillic}', raw):
        if common_ru and ('pu' in word or (p.endswith('p') and s.startswith('u'))):
            value += 0.634
    if len(raw) >= 2 and all(c == '·' for c in raw):
        value -= 1.0
    return value


