"""Component layers.1.mlp.down_proj:3269: the "pu" / "put" detector.

What it does: this component goes strongly negative on the letters p-u when they are
spelled as a word-piece: the token "put" (or "pu", "pun", "pur", "pus", "puted",
"putation", "Deputy", ...) and, when a word is split so that a "p" ends one token and
a "u" starts the next (lup|us, Lyap|un, Kap|u), on that "u" piece. It is near zero
on ordinary words that merely contain "pu" (public, input, output, purpose, push).
Cyrillic п/у count as p/u.

The program is a small rule with three cases:
  1. the piece is one of the put/pu fragments: -2.0 if it begins with a space (" put"),
     -4.4 if it does not ("put", "puted", "putation" inside a longer word);
  2. a short "u..." piece right after a token ending in "p": -1.5;
  3. the piece "t" right after a token containing "pu" (longput|t): -3.5;
  otherwise 0.
Everything else is predicted as 0 (the component's typical value).
"""

READS = ()

# Word-pieces built on the syllable "pu" or the root "put" (lowercase, no leading space).
PU_PIECES = {
    "pu", "pun", "puns", "pur", "pus", "pul", "puis", "pud",
    "put", "puts", "puted", "putting", "putation", "pute", "putas",
    "deputy", "disput", "disputes", "reput", "reputation",
}


def _norm(text):
    """Lowercase, and treat Cyrillic п and у as p and u."""
    return text.lower().replace("п", "p").replace("у", "u")


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    piece = _norm(raw).strip()
    # The previous token, if it is in the same document (the model resets at a document change).
    prev = ""
    if len(prefix.token_strings) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]:
        prev = _norm(prefix.token_strings[-2]).rstrip()

    if piece in PU_PIECES:
        value = -2.0 if raw[:1] == " " else -4.4
    elif piece[:1] == "u" and len(piece) <= 3 and prev[-1:] == "p":
        value = -1.5
    elif piece == "t" and "pu" in prev:
        value = -3.5
    else:
