    'second': (1.01, -0.35),
    'third': (0.76, -0.37),
    'foreign_first': (0.85, -0.26),
    'foreign_second': (0.28, -0.13),
    'Chinese': (1.16, -0.47),
    'contraction': (0.72, -0.07),
    'auxiliary': (0.29, -0.05),
    'negative': (0.81, -0.18),
    'literal': (0.50, 0.08),
