    if text == 'public':
        return 1.04
    if text == 'protected':
        return 0.71
    if text in {'def', 'fn', 'const'}:
        return 1.05
    if text in {'class', 'let'}:
        return 0.76
    if text == 'import':
        return -0.77
    if text in {'package', 'using'}:
        return -0.32
    if lower in {'when', 'after', 'before', 'then', 'while', 'during', 'once'}:
