                  r'新浪|本报|本報|本站|网|網|報|报|科技|财经|財經')
REGIONS = {x.name.casefold() for x in pycountry.countries}
STATES = [x.name.casefold() for country in ('US', 'CA', 'AU')
          for x in pycountry.subdivisions.get(country_code=country)]
REGIONS.update(STATES)
STATE_PREFIXES = {x[:n] for x in STATES for n in range(3, len(x) + 1)}
POSTAL = {x.code.split('-')[-1] for x in
          pycountry.subdivisions.get(country_code='US')}


@lru_cache(maxsize=4096)
