READS = ()

PHYSICS = set('''electric electrical magnetic electromagnetic nuclear thermal
kinetic potential mechanical chemical atmospheric solar gravitational radiant
renewable'''.split())
MATH = set('''arithmetic geometric harmonic mathematical logarithmic rational
parametric differential linear algebraic trigonometric'''.split())
SCIENCE = PHYSICS | MATH | set('''medical scientific technical math biology
biological genetic optical rotational surgical dielectric microwave structural
tensile'''.split())


def compound(modifier, head, title):
    if head == 'energy' and modifier in PHYSICS | {'heat'}:
        if modifier in {'electric', 'electrical', 'mechanical', 'chemical'}:
            return 5.3
        if modifier == 'potential' and title:
            return 5.3
        if modifier in {'solar', 'radiant', 'renewable'}:
            return 0.5
        return 1.8 if modifier == 'kinetic' else 2.6
    if modifier in {'electric', 'electrical', 'magnetic', 'electromagnetic'}:
        if head in {'field', 'fields'}:
            if modifier == 'electromagnetic':
                return 1.5 if head == 'field' else 1.0
            if modifier == 'electrical':
                return 3.0 if head == 'field' else 2.5
            return 5.3 if head == 'field' else 4.4
        if head in {'charge', 'resistance'}:
            return -1.8
        if head in {'flux', 'waves', 'force', 'power'}:
            return 1.6
    if modifier in {'arithmetic', 'geometric', 'harmonic'}:
        if head in {'progression', 'sequence', 'series'}:
            return 6.0
        if head in {'mean', 'means'}:
            return 4.8 if modifier == 'arithmetic' else 2.4
    if modifier in {'mathematical', 'electromagnetic', 'magnetic'}:
        if head == 'induction':
            return 2.8
    if modifier in MATH:
        if head.startswith('express'):
            return 2.7 if modifier == 'algebraic' else 1.2
        if head in {'equation', 'equations'}:
            if modifier in {'parametric', 'logarithmic', 'trigonometric'}:
                return 1.2
        if head == 'geometry' and modifier == 'algebraic':
            return -3.6
        if head in {'algebra', 'statistics'}:
            return -1.5
    if modifier == 'common' and head == 'ratio':
        return 2.5
    if modifier == 'time' and head in {'interval', 'period', 'periods'}:
        return 2.0 if head == 'interval' else 0.6
    if head in {'difference', 'differences'}:
        quantities = {'mass', 'weight', 'age', 'time', 'price', 'voltage', 'potential'}
        if modifier in quantities:
            return 2.3
    if modifier in {'heat', 'mass', 'energy'}:
        if head in {'transfer', 'exchange'}:
            return 2.3
    if head == 'loss' and modifier in {'weight', 'blood', 'heat', 'energy'}:
        return 2.1 if modifier in {'weight', 'heat'} else 1.3
    if head in {'difference', 'gradient', 'drops', 'drop'}:
        if modifier in {'pressure', 'temperature', 'concentration'}:
            return 3.2
    if modifier == 'temperature' and head in {'profile', 'distribution'}:
        return 3.4
    if modifier == 'health' and head == 'insurance':
        return 2.0
    if modifier in {'health', 'medical'} and head == 'care':
        return 0.55
    if modifier == 'mental' and head == 'health':
        return 0.5
    if modifier == 'heart' and head == 'failure':
        return 1.2
    if modifier == 'blood' and head == 'sugar':
        return -1.35
    if modifier == 'medical':
        if head == 'school':
            return 2.8
        if head in {'advisory', 'officer'}:
            return -4.0
        if head in {'research', 'evaluation'}:
            return -1.6 if title else -1.0
    if modifier in {'political', 'republican', 'democratic'}:
        if head in {'party', 'parties'}:
            return 2.4 if title else 1.4
    if modifier in SCIENCE:
        if head in {'professor', 'expert', 'intervention', 'telescope'}:
            return -1.0
        if head in {
            'axis', 'background', 'strength', 'algorithm',
            'constants', 'article', 'pain',
        }:
            return -1.0
    if modifier == 'income' and head == 'tax':
        return 1.0
    return 0.002


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    start = carry is None or carry[0] != doc
    text = token if start else (carry[1] + token)[-90:]
    value = -0.28 if start else 0.002
    match = re.search(r'([A-Za-z]+)[ _-]+([A-Za-z]+)$', text)
    if match and token[-1:].isalpha():
        modifier, head = match.groups()
        value = compound(modifier.lower(), head.lower(), head[0].isupper())
    if not start and token == 'care' and carry[1].lower().endswith('health'):
        value = 0.7
    if not token.isascii():
        simplified = SIMPLIFY(text[-12:])
        if token in {'能', '廠', '厂'}:
            if simplified.endswith('核能'):
                value = 4.2
            elif simplified.endswith('电能'):
                value = 6.5
            elif simplified.endswith('电厂'):
                value = 4.3
        elif simplified.endswith('医疗保障') and len(token) < 4:
            value = 3.4
    if not start and token == '··' and carry[1].endswith('··'):
        value = 0.785
    return (doc, text), value

"""Approximate a mixture of phrase-boundary responses.

The largest responses are to quoted punctuation in Wolfram box expressions.
A second family responds to institutional-name continuations after geographic
or formal modifiers. Code-keyword and file-opening pairs are handled separately.
There are also rules for 版 after 文/语/語, repeated middle
dots, and the unusually strong response to document-initial digits "12".
Everything else is left at zero, including ordinary-word fluctuations.
"""
import pycountry

READS = ()
GEOGRAPHIC_NAMES = {x.name for x in pycountry.countries}
GEOGRAPHIC_NAMES.update(x.name for x in pycountry.subdivisions)

# These are heads of academic or civic institution names, not arbitrary tokens.
INSTITUTIONS = {
    'Academy': 2.3, 'Institute': 1.6, 'University': 0.5,
    'College': 0.6, 'Association': 1.0, 'Society': 0.4,
    'Research': 1.0, 'Conference': 1.2, 'Symposium': 1.5,
    'Center': 0.6, 'Hospital': 1.2, 'Journal': 1.0,
}
NATIONAL_ADJECTIVES = set('''American British Chinese Korean Indian Australian
Brazilian Norwegian Russian Canadian Japanese French German Italian European
African Asian Jewish Malay'''.split())
FORMAL_MODIFIERS = {'National', 'International', 'Royal', 'State'}


def box_punctuation(token, previous):
    """Quoted literal delimiters/operators, and the brackets following them."""
    s, p = token.strip(), previous.strip()
    if token == 'Box' and p == 'Row':
        return -1.4
    if s.startswith('"'):
        if p in {'"]', '")', '"}'}:
            return 11.0
        if p == '"[' and s.startswith('",'):
            return 8.0
        if p == '"' and s.startswith('",'):
            return 6.5
        if len(s) > 1:
            ch = s[1]
            if ch in '[]':
                return 7.5 if token.startswith(' ') else 2.5
            if ch in '(){}':
                return 6.0
            if ch == ',' and not token.startswith(' '):
                return 4.7 if p == '"+' else 1.2
            if ch in '+-*/=,':
                return 6.0
            if ch == '\\':
                return 3.8
        if s in {'"', '",'}:
            return 1.2
    if p == '["' and s in {'(",', '-",', '+",'}:
        return 6.5
    if p == '"\\' and s == '[':
        return 3.8
    if s.startswith('\\['):
        return 1.5
    if s and all(ch in '],' for ch in s):
        return 4.0 if p == '")' else 2.5 if p == '"]' else 1.2
    return 0.0


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        previous, tail, box_code, position = '', '', False, 0
    else:
        _, previous, tail, box_code, position = carry
    token = prefix.token_strings[-1]
    tail = (tail + token)[-64:]
    box_code = (box_code or 'RowBox[' in tail or 'FractionBox[' in tail
                or (token.startswith(' "]')
                    and previous.rstrip().endswith('],')))
    s, p = token.strip(), previous.strip()
    value = 0.0
    if box_code:
        value = box_punctuation(token, previous)
    elif s in INSTITUTIONS:
        strength = 0.0
        if p in NATIONAL_ADJECTIVES:
            strength = 2.0
        elif p in FORMAL_MODIFIERS:
            strength = (1.5 if p == 'International' else
                        2.0 if p == 'Royal' else 1.0)
        elif p in GEOGRAPHIC_NAMES:
            strength = 1.5
        # East Asian academic-name prefixes were particularly strong in training.
        if p in {'Chinese', 'Korean'} and s in {'Academy', 'Institute'}:
            strength = 5.0
        value = strength * INSTITUTIONS[s]
    elif p in NATIONAL_ADJECTIVES | FORMAL_MODIFIERS:
        if s in {'Labor', 'Language', 'Literature', 'Agency', 'Development'}:
            value = -1.7
        elif s == 'Library':
            value = -1.0
        elif s == 'Lottery':
            value = -1.6
        elif s == 'foreign':
            value = -0.9
    if p == 'English' and s in {'Language', '-language'}:
        value = -2.8
    elif p == 'Chinese' and s == 'Taipei':
        value = -2.9
    elif p == 'Harvard' and s == 'Business':
        value = -1.5
    elif p == 'public' and s == 'interface':
        value = 2.5
    elif p == 'private' and s == 'readonly':
        value = 2.3
    elif p == 'package' and s == 'com':
        value = 1.9 if position == 1 else 0.3
    elif p == '<?' and s == 'php':
        value = 1.8 if position == 1 else 0.2
    elif len(token) > 1 and set(token) == {'·'}:
        value = 0.62
    if position == 1 and previous == '1' and token == '2':
        value = 3.58
    if s == '版' and p.endswith(('文', '语', '語')):
        value = -3.4 if p.endswith('文') else -2.3
    return (document, token, tail, box_code, position + 1), float(value)

"""Lexical severity, plus a spelling-sensitive 'ver' signal.

Severe/serious words, Chinese sternness characters, and Korean seriousness
or difficulty stems give large positive values. Smaller signals occur on
'from' after suffering and 'about' after concern. Short ver/vere fragments
are positive, whereas vers/versa and some vor/ven completions are negative.
These spelling rules also fire in unrelated names and words; this is not
a general measure of how serious a passage is. Unlisted tokens give zero.
"""
import re
from functools import lru_cache
import opencc

READS = ()
_TO_SIMPLIFIED = opencc.OpenCC('t2s')
ENGLISH_SEVERITY = {
    'serious': 5.0, 'seriously': 4.2, 'seriousness': 6.7,
    'severe': 3.6, 'severely': 3.1, 'severity': 3.2,
}


@lru_cache(maxsize=4096)
def simplified(text):
    return text if text.isascii() else _TO_SIMPLIFIED.convert(text)


def signal(token, previous):
    word, prev = token.strip().lower(), previous.strip().lower()
    if word in ENGLISH_SEVERITY:
        return ENGLISH_SEVERITY[word]

    # Normalize traditional Chinese; fused modifiers have weaker responses.
    han, prev_han = simplified(token), simplified(previous.strip())
    if han == '严':
        return 8.2
    if '严重' in han:
        return 8.0 if len(token) == 2 else 6.2 if len(token) == 3 else 4.5
    if '严肃' in han:
        return 5.5
    if '严格' in han:
        return 1.5
    if han in {'厉', '厉害'}:
        return 3.8
    if han in {'严峻', '郑重', '重大', '厳'}:
        return 2.8
    if han == '甚':
        return 1.5
    if prev_han == '严' and han in {'峻', '于', '厉'}:
        return 4.0
    if han == '害' and prev_han == '厉':
        return 4.5

    # Korean 어려- (difficult); byte-split 심각 (serious) is handled below.
    if token == '려':
        return 7.2 if previous.endswith('어') else 1.9
    if word == 'from' and re.search(r'\bsuffer(?:s|ed|ing)?$', prev):
        return 3.4
    if word == 'about' and prev in {
        'care', 'cares', 'cared', 'concerned', 'concerns', 'passionate'
    }:
        return 1.9
    if word == 'of' and prev in {'severity', 'seriousness'}:
        return 1.1
    if word.startswith('reveren'):
        return 2.5

    # Short spelling pieces, not arbitrary words containing these letters.
    if word == 'vere':
        return 6.5 if prev == 'se' else 6.0 if token[:1].isspace() else 3.5
    if word == 'ver':
        return 4.0 if prev == 'se' else 0.7
    if word.lstrip('-') == 'vers':
        return -6.0 if prev == 'vice' else -1.6 if token[:1].isspace() else -0.5
    if word == 'versa':
        return -4.2
    if word == 'vor':
        return -0.3
    if not token[:1].isspace():
        if word == 'a' and prev.endswith('vers'):
            return -3.7
        if prev.endswith('v'):
            if word in {'or', 'orr', 'ors', 'org', 'orge', 'oor'}:
                return -1.7
            if word in {'enn', 'env'} and prev == 'v':
                return -2.6
            if word in {'er', 'ér', 'ere', 'ering'}:
                return 2.5
        if word == 'ер' and prev.endswith('в'):  # Cyrillic ver
            return 2.4
        if word in {'h', 'hr', 'ehr', 'in'} and prev.endswith(('ver', 'vere')):
            return 3.3
        if word == 'rit' and prev.endswith('vé'):  # French vérité
            return 4.4
        if (word in {'e', 'ely', 'ity', 'a', 'o'} and prev.endswith('sever')) or (
            token == 'E' and previous == 'VER'
        ):
            return 5.8 if word not in {'a', 'o'} else 3.6
        if word == 'verity' and prev.endswith('se'):
            return 3.2
        if (word in {'io', 'ius'} and prev == 'ser') or (
            word == 'rio' and prev == 'sé'
        ):
            return 6.5 if prev == 'sé' else 4.4
        if word == 'ез' and prev.endswith('серь'):
            return 3.4
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous, tail = ('', b'') if carry is None or carry[0] != doc else carry[1:]
    token = prefix.token_strings[-1]
    tail = (tail + prefix.token_bytes[-1])[-24:]
    text = tail.decode('utf-8', errors='ignore')
    value = signal(token, previous)
    if token.strip() == '각' and text.endswith('심각'):
        value = 5.5
    elif token.strip() in {'심', '�'} and text.endswith('심'):
        value = 3.8
    return (doc, token, tail), value

programs.haiku:
"""Severity and gravity words. The component fires on words for 'serious' and 'severe'
(serious, severely, severity, Chinese 严重, Korean 엄, and the 'vere' stem of severe), and a
little on the preposition after a verb of suffering or concern ('suffer from', 'care about',
'concerned about'). It is negative on the 'vice versa' family ('versa', 'vers')."""
import unicodedata

READS = ()

# Stems of severe/serious words in several languages, accents stripped, lowercase.
# Value: typical activation on the token that completes the word.
SEVERE_STEMS = {"serious": 4.8, "seriou": 4.8, "serieu": 4.5, "serio": 5.0, "severe": 3.4,
                "severi": 3.5, "vere": 4.5, "seren": 4.0, "серьез": 3.5}
# Chinese / Korean tokens for 'serious' or 'severe'.
SEVERE_CJK = {"严重": 8.0, "嚴重": 7.5, "严": 6.6, "嚴": 7.0, "厳": 5.0, "엄": 5.0, "严肃": 5.4,
              "严峻": 4.0, "严厉": 2.9, "违反": 3.3, "重大": 1.8, "危": 1.6}
# Other words, including the 'vice versa' family, which is negative.
WEAK = {"ver": 0.7, "versa": -4.0, "vers": -1.5, "versi": -1.2, "vors": -2.7, "venv": -2.4,
        "优势": -1.8, "重要": -0.5}
SUFFER_WORDS = {"suffer", "suffers", "suffered", "suffering"}
CONCERN_WORDS = {"care", "cares", "cared", "caring", "concerned", "concern", "concerns",
                 "passionate", "worried", "deeply"}


def _letters(token):
    return "".join(ch for ch in unicodedata.normalize("NFKD", token)
                   if ch.isalpha() and not unicodedata.combining(ch)).lower()


def step(carry, prefix, upstream):
    # carry: (word being typed, previous word), lowercase, accents stripped.
    word, prev = ("", "") if carry is None else carry
    token = prefix.token_strings[-1]
    new_doc = len(prefix.document_ids) > 1 and prefix.document_ids[-1] != prefix.document_ids[-2]
    if new_doc:
        word, prev = "", ""
    if token[:1].isalpha():
        word = word + _letters(token)
    else:
        prev, word = word, _letters(token)
    value = 0.0
    for stem, v in SEVERE_STEMS.items():
        if word.startswith(stem):
            value = v
    for s, v in SEVERE_CJK.items():
        if token.strip() == s or (len(s) > 1 and s in token):
            value = v
    if word in WEAK:
        value = WEAK[word]
    if word == "from" and prev in SUFFER_WORDS:
        value = 3.5
    if word == "about" and prev in CONCERN_WORDS:
        value = 2.3
    return (word, prev), value

programs.sol:
"""Predict abbreviation punctuation, with explicit text-boundary exceptions.

Name initials and short abbreviations give positive stops, unlike sentence
ends or A--E answer/outline labels. Also recognize Chinese name separators,
mail-header colons, nested escaped quotes, code declarations, chat spacing,
and a few document-initial conventions. Other predictions are near zero.
"""
import calendar
from functools import lru_cache
import regex as re
from wordfreq import zipf_frequency

READS = ()
MONTHS = {s.lower() for s in calendar.month_abbr if s and s != 'May'}
REFERENCES = set('fig figs vol vols pp ed eds ch chap sec sect art arts '
                 'cf ibid op cit ib rev supp app ct cir dist publ proc ann'.split())
NUMBER_LABELS = {'no', 'nos', 'eq', 'eqs'}
UNITS = set('lb lbs oz ft in yd mi hr hrs min sec deg'.split())
BUSINESSES = set('inc ltd corp co bros'.split())
HONORIFICS = {'mr', 'mrs', 'ms', 'dr'}
RANKS = {'prof', 'rev', 'hon', 'st', 'lt', 'col', 'gen', 'capt'}


@lru_cache(maxsize=8192)
def short_word_stop(word):
    """Uncommon short words are more likely to be abbreviations."""
    low = word.lower()
    if low in MONTHS or low == 'sept':
        return 0.51
    if low in HONORIFICS:
        return 0.0
    if low in RANKS:
        return 0.43
    if low in NUMBER_LABELS:
        return 0.21
    if low in REFERENCES:
        if word.isupper():
            return 0.23
        return 0.42 if word.istitle() else 0.32
    if low in BUSINESSES:
        return 0.26
    if low in UNITS:
        return 0.19
    if word.isascii() and len(word) <= 5:
        frequency = zipf_frequency(low, 'en')
        if len(word) <= 4 and frequency < 4:
            return 0.2 if len(word) <= 3 else 0.16
        if len(word) <= 3:
            return 0.07
        if len(word) == 5 and frequency < 2.5:
            return 0.07
    return -0.005


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, b'', 0)
    _, tail, position = carry
    text = tail.decode('utf-8', errors='ignore')
    raw = prefix.token_bytes[-1]
    token = prefix.token_strings[-1]
    value = 0.0
    if position == 0:
        value = -0.3 if token[:1].isupper() else -0.1
        if token.isspace():
            value = -0.18
        elif token[:1].isdigit():
            value = -0.15
        elif token.startswith('<|'):
            value = -0.43
        if token == 'Title':
            value = -1.686
        if token == '<|endoftext|>':
            value = -4.577
    elif token == '.':
        match = re.search(r'([^\W\d_]+)$', text)
        word = match[1] if match else ''
        if len(word) == 1:
            if word.isupper():
                before = text[:-1]
                if re.search(r'(?:^|\n)[ \t]*$', before):
                    # A--E at line starts are often answer/outline labels.
                    value = -0.25 if word in 'ABCDE' else 0.6
                elif word in 'IVX':
                    value = 0.4
                else:
                    value = 0.95 if before[-1].isspace() else 0.45
            else:
                value = 0.085 if word in 'aeios' else 0.24
        else:
            value = short_word_stop(word) if word else -0.005
    elif token == ':':
        if position == 1 and text == 'Title':
            value = 23.692
        elif re.search(r'\bJoined$', text):
            value = 1.18
        elif re.search(r'\b(?:From|To)$', text):
            value = 0.45
        elif re.search(r'\bRe$', text):
            value = 0.24
    elif token == '·' and re.search(r'\p{Script=Han}$', text):
        value = 2.2
    elif len(token) > 1 and not token.strip('·'):
        value = 0.45
    elif token == '2' and position == 1 and text == '1':
        value = 2.789
    elif token == '\n\n':
        if text.endswith('</think>'):
            value = 0.407
        elif text.endswith('<think>'):
            value = 0.27
        elif text.endswith('<tool_response>'):
            value = 0.16
    elif token.startswith('\\"') and text.endswith('\\\\'):
        # A quote inside an already escaped string.
        value = 0.9 if token == '\\"' else 0.45
    elif token == 'index' and text.endswith('\n'):
        value = 0.36
    elif token == ' class' and re.search(r'public\s*$', text):
        value = 0.58
    elif (token in {'def', 'namespace'}
          and re.search(r'(?:^|\n)\s*$', text)):
        value = 0.4 if token == 'def' else 0.8
    return (doc, (tail + raw)[-200:], position + 1), value

"""A contextual detector for the year prefixes 19 and 20.

The second digit gets a positive response, especially after date words,
months, or citation markers. Formatting adjusts it; code-like text weakens it.
Embedded digit pairs are not fresh years. Chinese 一九 is also recognized.
Other activity is approximated by zero; this is not a full date parser.
"""
import calendar
import re
import regex

READS = ()
MONTHS = {s.lower() for s in
          list(calendar.month_name)[1:] + list(calendar.month_abbr)[1:]}
DATE_PREPOSITIONS = {
    'in', 'from', 'since', 'until', 'during', 'between', 'through'
}
DATE_WORDS = {
    'year', 'years', 'born', 'copyright', 'founded', 'established',
    'published', 'released', 'died'
}


def year_prefix_value(pair, separator, before):
    # A 20 buried in a longer number has a small negative response.
    if before[-1:].isdigit():
        return -0.04 if pair == '19' else -0.25

    value = 0.36 + (0.23 if pair == '19' else 0.0)
    if separator == ' ':
        value += 0.28
    if '\n' in separator:
        value += 0.12
    if separator.endswith('('):
        value += 0.04
        if separator.startswith(' '):
            value += 0.60
    if separator in ('-', '–', '—'):
        value += 0.23
    if separator == '/':
        value += 0.33

    words = re.findall(r'[a-z]+', before.lower())
    last_word = words[-1] if words else ''
    if last_word in DATE_PREPOSITIONS:
        value += 0.51
    if last_word in DATE_WORDS:
        value += 0.57
    if any(w in MONTHS for w in words[-5:]):
        value += 0.39

    tail = before[-60:].lower()
    if re.search(r'\bet\s+al\.', tail):
        value += 0.64
    if any(s in tail for s in
           (' = ', '==', '\\', 'http', 'www.', '[', ']', '{', '}', '*')):
        value -= 0.19
    if regex.search(r'\p{Script=Han}', before[-2:]):
        value += 0.73
    if re.search(r'\d\D{1,4}$', before):
        value -= 0.28
    return max(0.0, min(1.9, value))


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, separator, history = '', '', ''
    else:
        _, previous, separator, history = carry
    token = prefix.token_strings[-1]
    pair = previous + token
    value = 0.0
    if pair in ('19', '20'):
        value = year_prefix_value(pair, separator, history[:-1])
    elif token == '九' and previous.endswith('一'):
        value = 2.2
    return (doc, token, previous, (history + token)[-128:]), value

