"""Year-start detector for layers.1.mlp.down_proj component 3289.

What it does: the component fires on the SECOND digit of a two-digit number
that stands alone (not the tail of a longer number) and that can open a year
or a date: "9" in "1968" written as "19", "0" in "2015" written as "20", etc.
Concretely it is strongest on the "9" of "19" and the "0" of "20" when they
start a year in prose ("in 1968", "(1988", "June 20, 2015"), and weaker on the
second digit of other two-digit starts that can be days or years (30, 31, 11, 21).

The size is scaled by context: up after a year cue (a month name, "in",
"from", "the", "on", ...), down after words that make the number a plain
quantity ("than", "=", "is", "to", ...), and a little up when the number sits
inside parentheses, as in citations "(1988". Every other position predicts 0.
"""

READS = ()

DIGITS = set("0123456789")
MONTHS = {
    "January", "February", "March", "April", "May", "June", "July",
    "August", "September", "October", "November", "December",
}
YEAR_CUES = MONTHS | {"in", "In", "from", "the", "The", "on", "by", "since", "and", "of"}
QUANTITY_CUES = {"than", "=", "is", "at", "to", "for", "with", "as", "be", "if", "a", "about", "-", ":"}

# Activation scale for the two digits that begin a number, keyed by those two digits.
START_WEIGHT = {"19": 1.0, "20": 0.7, "30": 0.3, "31": 0.3, "11": 0.2, "21": 0.2, "12": 0.1}


def step(carry, prefix, upstream):
    s = prefix.token_strings
    t = len(s) - 1
    if t < 3 or s[t] not in DIGITS or s[t - 1] not in DIGITS or s[t - 2] in DIGITS:
        return carry, 0.0
    weight = START_WEIGHT.get(s[t - 1] + s[t], 0.0)
    if weight == 0.0:
        return carry, 0.0
    word = s[t - 3].strip()
    if word in YEAR_CUES:
        weight *= 1.5
    elif word in QUANTITY_CUES:
        weight *= 0.4
    if s[t - 2].strip() == "(":
        weight += 0.2
    return carry, float(weight)

