from opencc import OpenCC

READS = ()
_simplify = OpenCC('t2s')
FITTING = {'配合', '结合', '搭配'}
REFERENCE = {'参考', '参照'}
ANOTHER = {'另一', '另一个', '另外', '另'}
OTHER = {'其他', '其它'}
SELECT = {'选', '选取', '选购', '挑选'}
CONDUCT = {'行为', '的行为'}
NORMS = {'规范', '健全', '完善'}

