    elif word in REFERENCE:
        value = -0.7
    elif word in ANOTHER:
        value = -0.5
    elif word in OTHER:
        value = -0.15
    elif word == '加':
        value = -0.35
    elif word in SELECT:
        value = -0.3 - 0.3 * clause_start
    elif word in {'各', '各项'}:
        value = -0.25 - 0.4 * clause_start
    elif word == '同时':
        value = -0.08 - 0.35 * clause_start
    elif word == '与':
        value = -0.12
    elif word in CONDUCT:
        value = 0.8
    elif word in NORMS:
        value = 0.3
    elif word in {'类型', '类型的'}:
        value = 0.3
    elif word == '型' and previous.endswith(('类', '定')):
        value = 0.65
    elif word in {'式', '态', '句'} and previous.endswith(
        ('型', '形', '语', '词', '体', '动词')
    ):
