programs.sol:
"""A spelling-dependent pulse at the start of a document.

The pulse is usually positive for unspaced capitals, numerals and several
non-Latin scripts, and negative for indented or space-prefixed fragments.
Repeated copies of the opening token retain the pulse; later text is quiet.
Very common English words receive smaller capital-letter pulses; declaration
starters receive negative ones, especially the class-definition keyword.
These broad rules do not reproduce the irregular amplitudes of individual words.
"""
import unicodedata
from wordfreq import zipf_frequency

READS = ()
DECLARATIONS = {
    'class', 'def', 'struct', 'int', 'string', 'import', 'from', 'package',
    'namespace', 'public', 'private', 'protected', 'void', 'const', 'using',
    'export', 'asm',
}


def opening_value(s):
    p = s.strip()
    if s.startswith('<|'):
        return 0.0
    if not p:
        if '\t' in s:
            return -3.4
        return -1.8 if len(s) >= 3 and '\n' not in s else 0.0
    spaced = s[0].isspace()
    if p == 'class' and not spaced:
        return -7.1
    if p in DECLARATIONS:
        return -2.4
    if len(p) == 1 and p.isascii() and p.isdigit():
        n = int(p)
        if n == 0:
            return 0.3
        if n <= 3:
            return 3.5 - 0.9 * n
        return -0.5 if n == 9 else 0.65
    if '\ufffd' in p:
        return 1.0
    name = unicodedata.name(p[0], '')
    if 'CYRILLIC' in name:
        return 1.0 if spaced else 2.5
    if 'ARABIC' in name:
        return 1.9 if spaced else 3.7
    if 'KATAKANA' in name:
        return 2.5
    if 'HANGUL' in name:
        return 1.2
    if 'GREEK' in name:
        return 0.5 if spaced else 2.0
    if 'THAI' in name:
        return 3.5
    if 'CJK' in name or 'HIRAGANA' in name:
        return -0.15
    if p.isascii() and p.isalpha():
        if spaced:
            return -0.15 if len(p) <= 3 else -0.55
        if p[0].isupper():
            frequency = zipf_frequency(p.lower(), 'en')
            if frequency >= 6.0:
                return 0.0
            return 1.7 if frequency < 4.0 else 1.15
        return 0.3 if len(p) <= 2 else -0.4
    if set(p) <= set('·^'):
        return 2.7
    if not spaced and (p[0] in "('/<" or p.startswith('#!')):
        return 2.5
    if p.startswith('#include'):
        return 1.6
    if p == '#':
        return -0.9
    return -0.3 if spaced else 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token_id = prefix.token_ids[-1]
    if carry is None or carry[0] != doc:
        value = opening_value(prefix.token_strings[-1])
        return (doc, token_id, value), value
    _, first, value = carry
    if token_id != first:
        return (doc, None, 0.0), 0.0
    return carry, value

