"""Document-initial token detector for layers.1.mlp.down_proj:3291.

What the component does: it is silent almost everywhere. Its large activations come on the
first token of each document (the token right after <|endoftext|>) and on the first token of
each row (a row may begin partway through a document). Since that token has no earlier
context, its value depends on what kind of token it is:
  - a non-Latin capital letter (Cyrillic, Greek, Arabic, ...): strongly positive;
  - a capitalised Latin word, especially a short one or a fragment (names, titles): positive;
  - a digit: positive;
  - a capitalised function word (The, This, When, If, ...): about zero;
  - a lowercase word or punctuation: about zero;
  - a space-led word (a mid-sentence word starting a row): slightly negative;
  - a programming keyword (use, class, int, from, ...) or an indent (tab, several
    spaces), i.e. source code: negative.
Every later position predicts 0. The values are category means fitted on training rows.
"""

READS = ()

FUNCTION_WORDS = frozenset(
    "The This That These Those When What Which Who Where Why How If In On At For And But Or "
    "So It Its I We You They He She A An As By With From Our Your His Her There Here Now Also "
    "Not No Yes Do Does Is Are Was Be Can Will Would Should Could Have Has Had Just Only Some "
    "All Any Each Every Many Most Other Such Then Than Because Since While Although Though "
    "After Before Over Under Into Out Up Down About Between Through During Without Within".split()
)

CODE_WORDS = frozenset(
    "use class int from string char case static def import return if for while var let "
    "const public private void self new function struct include else try none true false "
    "null str bool float double long short template namespace package".split()
)

MEAN = {
    "non_latin_capital": 4.0,
    "digit": 1.1,
    "capital_short": 1.4,
    "capital_long": 0.7,
    "function_word": -0.1,
    "non_latin_other": 0.6,
    "lowercase": 0.0,
    "punctuation": 0.05,
    "space_word": -0.3,
    "space_other": -0.1,
    "indent": -1.9,
    "code_word": -1.0,
}


def category(s):
    if not s:
        return "punctuation"
    word = s.strip()
    c = s[0]
    if c == "\t" or s.startswith("  "):
        return "indent"
    if c in " \r\n":
        if word.lower() in CODE_WORDS:
            return "code_word"
        return "space_word" if word[:1].isalpha() else "space_other"
    if c.isdigit():
        return "digit"
    if c.isascii() and c.isalpha():
        if word.lower() in CODE_WORDS:
            return "code_word"
        if c.isupper():
            if word in FUNCTION_WORDS:
                return "function_word"
            return "capital_short" if len(word) <= 4 else "capital_long"
        return "lowercase"
    if c.isalpha():
        return "non_latin_capital" if c.isupper() else "non_latin_other"
    return "punctuation"


def step(carry, prefix, upstream):
    # a document (or row) starts at its first token: the document label changes there
    starts = len(prefix) == 1 or prefix.document_ids[-1] != prefix.document_ids[-2]
    if not starts:
        return carry, 0.0
    return carry, float(MEAN[category(prefix.token_strings[-1])])

