# Relative strengths of escaped Markdown, regex and TeX punctuation.
PUNCTUATION = {
    '!': 1.0,
    '*': 0.58,
    '$': 0.48,
    '.': 0.68,
    '/': 0.52,
    '`': 0.50,
    '-': 0.45,
    '+': 0.45,
    '^': 0.40,
    '&': 0.30,
    '_': 0.24,
    '{': 0.23,
    '}': 0.10,
    '[': 0.15,
    ']': 0.15,
    ',': 0.08,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, position = '', 0
    else:
        _, previous, position = carry
    s = prefix.token_strings[-1]
    text = s.lstrip()
    value = 0.0

    # Escapes wholly within one token. Math brackets are mostly delimiters;
    # internal dollar/backtick escapes are weaker than separate tokens.
    for i, ch in enumerate(s[1:], 1):
        if s[i - 1] == '\\':
            strength = PUNCTUATION.get(ch, 0.0)
            if ch in '$`_':
