    # A run of three or more backslashes is nested escaping.
    if text and not text.strip('\\'):
        value = max(value, max(0.0, 0.40 * (len(text) - 2) + 0.05))

    if previous.endswith('\\') and text:
        first = text[0]
        if first == '\\':
            value += 0.40
        else:
            value += PUNCTUATION.get(first, 0.0)
            if first in '*!' and first in previous:
                value += 0.18

