        # quote-plus-closing-syntax tokens receive a smaller pulse.
        if text.startswith('\\"'):
            tail = text[2:]
            if not tail:
                value = 1.20 + (0.25 if previous.startswith(' ') else 0.0)
            elif tail.startswith('>'):
                value = 0.18
            elif tail.startswith('\\'):
                value = 0.95
            elif tail.startswith(','):
                value = 0.80
            else:
                value = 0.55
    elif text.startswith('\\\\"'):
        value = 0.75

    if position == 0 and s == 'Title':
        value = -0.52
    elif position == 1 and previous == 'Title' and s == ':':
        value = -3.80
    return (doc, s, position + 1), value

