AFTER_N = (
    (-0.422, -1.698, -0.965,
     -0.145, -0.312, -0.692,
     -0.261),                    # lone n
    (-0.187, -0.595, -0.352,
     -0.084, -0.311, -0.487,
     -0.177),                   # non-vowel + n
    (-0.103, -0.263, -0.171,
     -0.026, -0.132, -0.037,
