        value = 4.2 if length <= 2 else 2.8 if length == 3 else 1.9
        if previous_length == 4:
            value *= 0.55
    elif pair == 'ii' and length <= 4 and previous_length <= 3:
        if previous[-1:].isupper():
            value = 5.0 if length <= 3 else 2.0
        elif previous_length > 1:
            value = 3.0 if length <= 3 else 1.4
        else:
            value = 0.3
