"""Approximate a local spelling contrast seen in the training activations.

B+al/ai/acc and bal/bai fragments tend negative; selected al endings tend
positive. Longer fragments dilute the context response. Separate rules
handle 白, some kana transitions, and repeated middle dots. Cyrillic
transliterations receive weaker versions of the Latin rules. Only the
current and previous tokens are inspected, resetting at document boundaries.
Other contexts stay near zero; these rules do not explain every activation.
"""
from anyascii import anyascii
import regex

READS = ()


def spelling(text):
    # Cyrillic has corresponding al/ai spellings; accented Latin and kana
    # must not be mistaken for unaccented Latin fragments.
    if regex.search(r'\p{Script=Cyrillic}', text):
        return anyascii(text).lower()
    return text.lower()


def local_value(raw, old):
    text = raw.decode('utf-8', errors='ignore')
    previous = old.decode('utf-8', errors='ignore')
    if text == '白' or (len(raw) < 3 and (old + raw).endswith('白'.encode())):
        return -4.2
    if '白' in text:
        return -1.3
    if text and set(text) == {'·'} and previous.endswith('·'):
        return -2.15
    if text == 'ラ':
