        if p.endswith(('cc', 'us')):
            return 2.7 * scale
        if p.endswith(('z', 'x')):
            return 1.3 * scale
        if p.endswith(('ng', 'ak')):
            return -2.5 * scale
        if p.endswith(('am', 'aw')):
            return -1.5 * scale
        if p.endswith('uth'):
            return 2.5 * scale
        if p.endswith(('a', 'l', 'k', 'h', 'g')):
            return -0.8 * scale
        if p.endswith(('tr', 'or', 'ss')):
            return 0.9 * scale
        if s in ('ala', 'ald', 'alm', 'aler'):
            return -0.6
    if s in ('acc', 'acci') and p.endswith('b'):
        return -3.4
    if s == 'sal':
        return 0.7
    if s == 'ai':
        if p.endswith('b'):
            return -4.8
        if p.endswith('al'):
            return -3.0
        if p.endswith('l'):
            return -1.3
    if s.strip() in ('bal', 'bald', 'bale', 'bali'):
        return -1.3
    if s.strip() == 'bai':
        return -3.5
    if s == 'ba' and p.endswith('al'):
        return -2.2
    if s in ('log', 'logical') and p.endswith(('tal', 'tro')):
        return 2.1
    if s == ' stal':
        return 2.0
    if s == 'ral' and p and p[-1].isalpha():
        return 0.8
    if s == 'cal' and p.endswith('oc'):
        return 2.7
    return -0.002


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    old = carry[1] if carry is not None and carry[0] == doc else b''
    raw = prefix.token_bytes[-1]
    value = local_value(raw, old)
    return (doc, raw), value

"""A homework-forum formatting signal, not a general detector of mathematics.

Positive predictions mark short school-subject headings and their newlines,
bylines, dates/times, and question-list furniture. Recognized forum furniture
strengthens later subject headings. Chat-formatted documents suppress this
heading detector. Smaller cues include help requests, view counts and
exclamations.
Everything else is zero; small token-specific fluctuations are not modeled.
"""
import re

READS = ()
SUBJECTS = (
    'math', 'mathematics', 'algebra', 'geometry', 'calculus', 'precalculus',
    'trigonometry', 'statistics', 'probability', 'physics', 'chemistry',
    'science', 'biology', 'english', 'spanish', 'history', 'economics',
)
DATE = re.compile(r'(?:January|February|March|April|May|June|July|August|'
                  r'September|October|November|December) \d{1,2}, \d{4}')
WEEKDAY = re.compile(r'^(?:Monday|Tuesday|Wednesday|Thursday|Friday|Saturday|Sunday),')
MARKER = re.compile(r'^\s*(?:\d+\.\s*)?(?:#{1,6}|•)\s*')


def topic(title):
    """A subject, possibly still being spelled, with common title qualifiers."""
    for word in SUBJECTS:
        if len(title) >= 3 and word.startswith(title):
            return True
        if title.startswith(word):
            rest = title[len(word):].strip()
            if not rest or rest.isdigit() or rest in ('-', '- ,'):
                return True
            if rest.startswith(('/', '(')):
                return True
            if 'need help'.startswith(rest) and rest.startswith('need'):
                return True
            if rest.startswith('and ') and topic(rest[4:]):
                return True
    return False


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', '', False, False)
    _, tail, line, forum, chat = carry
    s = prefix.token_strings[-1]
    low = s.strip().lower()
    newline = '\n' in s
    chat = chat or s == '<|im_start|>'
    value = 0.0

    # Subject labels in question lists and at the beginnings of posts.
    full_line = (line + s).split('\n')[0]
    marker = MARKER.match(full_line)
    title = full_line[marker.end():] if marker else full_line
    title = re.sub(r'^(?:(?:college|integrated|physical) |\d+(?:st|nd|rd|th) grade )+',
                   '', title.lower().strip())
    subject = not chat and len(title) < 65 and topic(title)
    numbered = bool(re.match(r'^\s*\d+\.\s*#{2,}', full_line))
    bullet = marker and '•' in full_line
    if subject:
        value += (3.35 if marker else 0.65) if newline else (1.1 if marker else 0.0)
        value += (5.0 if newline else 2.95) if forum else 0.0
        if numbered and newline:
            value -= 2.4
        if not newline and '?' in tail[-180:]:
            value += 0.4
        if bullet:
            if newline:
                value = 2.6
            else:
                value += 4.0 if '-' in s else -0.55
        # A page's initial top-level category is stronger than an internal title.
        if tail == line and re.match(r'^#\s', full_line):
            value += 3.5 if newline else 2.3
        if numbered or (newline and '?' in tail[-180:]):
            forum = True
    elif forum and marker and newline and not chat:
        value += 1.1
    if forum and '#' in s and re.search(r'\d+\.\s*$', tail):
        value += 2.7

    # Author fields, including the characteristic empty "posted by ." field.
    posted = low == 'by' and re.search(r'(?:^|\n)posted\s*$', tail)
    asked = low == 'by' and re.search(r'\basked\s*$', tail, re.I)
    posts = low == 'by' and re.search(r'# Posts\s*$', tail)
    if posted:
        value += 3.2
        if any(tail.lower().endswith(w + '\n\nposted') for w in SUBJECTS):
            value += 9.0
    if asked:
        value += 5.2
    if posts:
        value += 11.3
    if low == '#' and re.search(r'\bTotal\s*$', tail):
        value += 11.1
    if newline and '.' in s and re.search(r'posted by(?: on)?\s*$', tail):
        value += 10.9
    if not newline and re.search(r'asked by\s*$', tail):
        value += 0.7
    if low == 'on' and re.search(r'asked by [^\n]{1,35}$', tail):
        value += 1.2

    # Dated forum timestamps: the attached am/pm is especially strong.
    dated = bool(DATE.search(tail[-100:]))
    timed = s in ('am', 'pm') and re.search(r'\d{1,2}:\d{2}$', tail)
    if timed and dated:
        value += 13.3 if re.search(r' at \d{1,2}:\d{2}$', tail) else 1.8
    if low == 'by' and re.search(r'\d{1,2}:\d{2}[ap]m\s*$', tail):
        value += 7.3
    if low == 'at' and dated and WEEKDAY.match(line):
        value += 3.1
    if newline and re.search(r'\d{1,2}:\d{2}[ap]m by [^\n]{1,50}$', tail):
        value += 3.1

    similar = s.lstrip() == 'Questions' and tail.endswith('Similar')
    results = low == 'results' and tail.endswith('Number of')
    if similar:
        value += 13.7 if re.search(r'## Similar$', tail) else 7.4
    if results:
        value += 4.7
    if forum and newline and ('...' in s or '…' in s):
        value += 2.1
    forum = bool(forum or posted or asked or posts or (timed and dated) or similar or results)

    # Weaker conversational cues.
    if low == 'views' and re.search(r'\d$', tail):
        value += 0.4
    if low == 'more' and tail.endswith('View'):
        value += 0.55
    if low in ('help', 'please', 'explain', 'check') and re.search(
        r'(?:please|pls|plz|can you|could you|can someone|can somebody|'
        r'could someone|any|me|you|this)\s*$', tail, re.I):
        value += 0.33
    if low == 'please' and '?' not in tail[-80:] and re.search(
        r'\b(?:help|comment|explain)\b', tail[-80:], re.I):
        value += 0.9
    if len(s.strip()) >= 2 and set(s.strip()) == {'!'}:
        value += 0.38
    return (doc, (tail + s)[-300:], (line + s).split('\n')[-1][-150:], forum, chat), value

programs.haiku:
"""layers.1.mlp.down_proj:3298 -- fires on the boilerplate of scraped homework / Q&A forum pages.

What it responds to (all of it is text a web scraper picks up from student Q&A sites):
  * the byline "asked by <user> on <date>" or "posted by <user>", when the verb starts a
    line (after a question body or a "# subject" title): strongest on the "by" token;
  * the separator " ." that follows an empty byline ("posted by on ."): fires strongly;
  * "Similar Questions" (the related-questions block);
  * a time stamp "... at 8:47pm by <user>": the "pm"/"am" token and the "by" after it;
  * subject headers of question lists: a line holding a "#" heading and a school subject
    ("# math", "12. ## Chemistry") fires on the newline that closes it, most strongly when
    the item is numbered; a bare subject tag line ("Physics") fires on the newline after it
    when a date or a question sits just above it.

Everything else predicts 0: the component is near zero on ordinary text.
The rules read only the current token and a few tokens before it, within the same document.
"""
import re

READS = ()

# School subjects that head homework posts on Q&A sites.
SUBJECTS = frozenset({
    "math", "maths", "mathematics", "algebra", "prealgebra", "calculus", "calc", "precalculus",
    "precalc", "trig", "trigonometry", "geometry", "statistics", "stats", "chemistry", "chem",
    "biochemistry", "physics", "science", "biology", "geology", "astronomy", "college",
})
TIME = re.compile(r"at \d{1,2}:\d\d\s?$")  # "... at 8:47" just before "pm"/"am"


def step(carry, prefix, upstream):
    toks, docs, t = prefix.token_strings, prefix.document_ids, prefix.position
    cur = toks[t].strip()
    raw = toks[t]

    def back(k):
        """The token k steps before this one, or "" if it is in an earlier document."""
        j = t - k
        if j < 0 or docs[j] != docs[t]:
            return ""
        return toks[j]

    value = 0.0
    if cur == "by":
        verb = back(1).strip()
        if verb == "ed" and back(2).strip() == "ask":  # "asked" is split as "ask" + "ed"
            verb = "asked"
        if verb in ("asked", "posted", "Posts"):
            # a byline: the verb opens a line (a newline or "#" just before it), or a page start
            start = back(3) if verb == "asked" else back(2)
            value = 12.0 if ("\n" in start or "#" in start or start == "") else 2.0
        elif verb in ("am", "pm") and TIME.search("".join(back(k) for k in range(6, 1, -1))):
            value = 5.0  # "by" right after a time stamp
    elif cur == "Questions" and back(1).strip() == "Similar":
        value = 14.0  # "## Similar Questions"
    elif cur in (".", ".\n\n") and back(1).strip() in ("by", "on") and "posted" in (
        back(2).strip(), back(3).strip()
    ):
        value = 10.0  # the separator after an empty "posted by on"
    elif cur in ("pm", "am") and TIME.search("".join(back(k) for k in range(5, 0, -1))):
        value = 3.0  # the "pm" of a time stamp, which is often followed by "by <user>"
    elif "\n" in raw:
        # the line this newline closes, and the text before that line
        line, q = [], t - 1
        while q >= 0 and docs[q] == docs[t] and "\n" not in toks[q] and t - q < 12:
            line.append(toks[q].strip().lower())
            q -= 1
        line.reverse()
        line_text = "".join(line)
        if any(x in SUBJECTS for x in line):
            prev, q2 = [], q - 1
            while q2 >= 0 and docs[q2] == docs[t] and "\n" not in toks[q2] and q - q2 < 40:
                prev.append(toks[q2])
                q2 -= 1
            prev_text = "".join(reversed(prev)).strip()
            numbered = any(x.rstrip(".").isdigit() for x in line)  # "12." before "##"
            if "#" in line_text:
                value = 6.0 if numbered else 0.0  # "# math" titles alone are not reliable
            elif len(line) <= 3 and line_text in SUBJECTS and raw == "\n":
                # a bare subject tag, after a date line (strong) or a question (weaker)
                value = 6.0 if re.search(r"\d{4}", prev_text) else 3.0
    return carry, value

programs.sol:
"""A local grammatical detector for forms of 'do'.

Uninflected 'do' is strong after 'to', a modal, negation, or an inverted
auxiliary ('what can I do?'), but weak in finite 'I do'/'how do ...'.
'Doing' is strong throughout, especially as a gerund after a preposition.
'Done' is strongest in the perfect ('have done'), less so in the passive.
Split spellings of 'done' and 'doing(s)' are also recognized, including
underscore-delimited identifiers. These are approximate grammatical cues.
"""
import re

READS = ()
MODALS = {'can', 'could', 'will', 'would', 'should', 'must', 'may', 'might'}
BE = {'am', 'is', 'are', 'was', 'were', 'be', 'been', 'being'}
HAVE = {'have', 'has', 'had'}
PREPOSITIONS = {'of', 'in', 'by', 'from', 'on', 'after', 'before', 'without'}


def words_before(text):
    text = text.lower().replace('’', "'")
    text = re.sub(r"n't\b", ' not', text)
    for ending, expansion in (("'ve", ' have'), ("'ll", ' will'),
                              ("'d", ' would'), ("'re", ' are'),
                              ("'m", ' am'), ("'s", ' is')):
        text = text.replace(ending, expansion)
    text = re.split(r'[.!?;,\n]', text)[-1]
    return re.findall(r'[a-z]+', text)[-5:]


def strength(token, previous):
    word = token.strip().lower()
    # A suffix can complete an action word begun in the preceding token.
    if token.lower() == 'one' and re.search(r'(?:^|[\W_])d$', previous, re.I):
        return 7.0
    if token.lower() in {'ing', 'ings'} and re.search(
            r'(?:^|[\W_])do$', previous, re.I):
        return 4.6 if token.lower() == 'ings' else 3.4
    if word == 'doings':
        return 4.6
    if word not in {'do', 'doing', 'done', 'does', 'did'}:
        return 0.0
    words = words_before(previous)
    last = words[-1] if words else ''
    if word == 'does':
        return -0.5 if last in {'how', 'what', 'why'} else -0.25
    if word == 'did':
        return -0.25 if last in {'how', 'what', 'why'} else -0.03
    if word == 'doing':
        if last in PREPOSITIONS or last in {'while', 'when'}:
            return 6.1
        return 3.9 if last in BE else 4.4
    if word == 'done':
        recent = words[-3:]
        if any(w in HAVE for w in recent) and not any(w in BE for w in recent):
            return 5.4
        if last == 'work':
            return 0.8
        if last in {'is', 'are', 'being', 'well'}:
            return 1.5
        return 2.0 if token[:1].isspace() else 1.4

    # The bare verb needs an infinitival or auxiliary frame to be strong.
    if last == 'to':
        before_to = words[-2] if len(words) > 1 else ''
        if before_to == 'what':
            return 6.0
        if before_to in {'how', 'way'}:
            return 9.7
        return 9.0 if previous.rstrip().endswith('To') else 7.8
    if last in {'not', 'cannot'}:
        return 8.7
    if last in {'and', 'or'}:
        return 1.6
    if any(w in MODALS for w in words[-3:]):
        return 7.5
    if (len(words) >= 2 and words[-2] in {'do', 'does', 'did'}
            and last in {'i', 'you', 'we', 'they', 'he', 'she', 'it'}):
        return 11.0 if 'how' in words[-4:] else 7.7
    if last in {'me', 'us', 'him', 'her', 'them', 'lets'} or 'let' in words[-3:]:
        return 6.0
    if not previous or previous.endswith('<|endoftext|>'):
        return 1.7 if token.strip() == 'Do' else 2.5
    return -0.25


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    value = strength(token, previous)
    return (doc, (previous + token)[-120:]), value

programs.haiku:
"""Fires on the verb "do" and its forms "doing" and "done".

A bare "do" (the base verb) after "to", a modal ("can", "will", "should", ...),
"not"/"n't", or "me" fires strongly; "doing" fires moderately; "done" fires
strongly after "have/has/had" and weakly after "be/is/was". Other uses of "do"
(after a subject pronoun, "how do", "what do", a comma) stay near zero.
"""

READS = ()

BARE_CUES = {"to", "can", "will", "should", "could", "must", "would", "may",
             "might", "cannot", "not", "me", "just", "also", "t", "ll", "d"}
PERFECT_CUES = {"have", "has", "had", "ve"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    prev = ""
    if len(prefix) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]:
        prev = prefix.token_strings[-2].strip().lower().replace("’", "'").lstrip("'")
    if word == "do":
        return carry, 8.0 if prev in BARE_CUES else 0.5
    if word == "doing":
        return carry, 4.5
    if word == "done":
        return carry, 5.0 if prev in PERFECT_CUES else 2.0
    return carry, 0.0

programs.sol:
"""Detect age words and age suffixes, rather than the number being described.

English 'old' responds strongly after a duration, and 'age' responds more
strongly in 'at/of age' and 'the age'.  'All ages' is strong; historical
ages and the idiom 'for ages' are weaker or negative.  Chinese, Japanese,
Korean and Vietnamese age markers have separate response scales.
Generation/century morphemes and the Korean month unit respond weakly.
Unrelated background responses are left at zero. Only a short text tail
is kept, resetting at each document boundary.
"""
import re

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    number_before = bool(re.search(r'\d\s*$', tail))
    value = 0.0

    if word in ('old', '-old', 'olds', '-olds'):
        duration = re.search(
            r'(-?)(years?|months?|weeks?|days?)[ -]?$', tail, re.I
        )
        if duration:
            unit = duration[2].lower().rstrip('s')
            if word.endswith('olds'):
                value = 2.0
            elif word == '-old' or duration[1]:
                value = 3.7 if unit in ('year', 'month') else 2.5
            elif unit == 'year':
                value = 5.7 if duration[2].lower() == 'years' else 4.4
            elif unit == 'month':
                value = 4.8
            else:
                value = 2.9
            # Direct statements of age tend to respond more than modifiers.
            if re.search(r'\b(?:am|is|are|was|were)\b[^.!?\n]{0,25}$', tail):
                value += 0.7
        elif word == 'old' and re.search(r'\bhow\s*$', tail, re.I):
            value = 0.9
    elif word in ('age', 'ages') and (
        token[:1].isspace() or not tail or not tail[-1].isalpha()
    ):
        previous = re.findall(r"[\w']+", tail.lower())[-1:]
        previous = previous[0] if previous else ''
        value = 1.2 if word == 'age' else 0.7
        if previous in ('the', 'this', 'that'):
            value = 2.3
        if previous in ('at', 'of'):
            value = 3.1
        if previous in ('my', 'your', 'his', 'her', 'its', 'their', 'our'):
            value = 0.6
        if word == 'ages':
            if previous == 'all':
                value = 4.2
            elif previous in ('both', 'different', 'various'):
                value = 2.5
            elif previous in ('for', 'in'):
                value = -1.7
        if previous in (
            'dark', 'middle', 'golden', 'stone', 'bronze', 'iron',
            'ice', 'digital', 'industrial', 'modern', 'new',
        ):
            value = -0.8 if word == 'ages' else 0.0
    elif any(mark in word for mark in '岁歲歳'):
        if word in ('岁', '歲'):
            value = 10.3
        elif word == '歳':
            value = 7.2
        elif word.endswith('月'):  # 岁月: years / passage of time
            value = 2.4
        else:  # age marker merged with a grammatical suffix
            value = 6.8
    elif word == '세':  # Korean age suffix; also occurs inside other words
        value = 10.7 if number_before else 3.1
    elif word == 'tuổi':  # Vietnamese age / years old
        value = 5.4
    elif word in ('世', '世纪', '世紀', '세계'):
        # Generation / century morphemes, also used to mean 'world'.
        value = 4.3 if word == '世' and number_before else 1.3
    elif word == '월':  # Korean month unit
        value = 1.1
    elif word == '살':  # native Korean age unit
        value = 1.3

    return (doc, (tail + token)[-100:]), value

"""A detector for prepositional idioms, especially phrases starting with 'on'.

Months after 'on' and spaces introducing dates give negative values.
'On top of', 'on to', 'over time', 'onto', and a small family of
bare-noun 'on' adverbials give positive values. Relative constructions
like 'which to' and 'at which point' also give positive values.
Unrecognized contexts are left at zero.
"""
import calendar
import re

READS = ()
MONTHS = frozenset(m.lower() for m in calendar.month_name if m)
ON_ADVERBIALS = frozenset('''
    stage board foot location set earth campus
    file paper film video record air display
    strike loan duty fire demand tap purpose average occasion target
    appeal
'''.split())


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    history = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    words = re.findall(r"[a-z]+", history.lower())
    prev = words[-1] if words else ''
    # Require an immediately preceding word, not one across punctuation.
    adjacent = bool(re.search(r'[a-z]\s*$', history.lower()))
    value = 0.0
    if not history and word == 'on':
        value = -3.5
    elif word == 'onto':
        value = 3.5
    elif word == 'o' and re.search(r'\bont$', history.lower()):
        value = 6.0
    elif word == 'of' and re.search(r'\bon top$', history.lower()):
        value = 8.2
    elif adjacent and prev == 'on':
        if word in MONTHS:
            value = -4.0
        elif token == ' ':
            value = -2.1
        elif word == 'top':
            value = 6.5
        elif word in ('to', 'time', 'end'):
            value = 5.5
        elif word in ON_ADVERBIALS:
            value = 3.2
        elif word == 'one':
            value = -1.3
    elif adjacent and prev == 'over' and word == 'time':
        value = 5.1
    elif adjacent and prev == 'which':
        if word in ('to', 'time'):
            value = 6.4
        elif word in ('point', 'case'):
            value = 4.3
    elif token == ' ' and adjacent and prev in MONTHS:
        if len(words) > 1 and words[-2] in ('on', 'in'):
            value = -1.3 if words[-2] == 'on' else -0.8
    return (doc, (history + token)[-80:]), value

"""Tokenization-sensitive SAT/SIT spelling pulses.

Short sat tokens and sit/sits/sitting give negative pulses. Unbroken
s|at, s|itt... and similar split syllables also do, especially uppercase
AT. Longer sat stems (except satis...) are weaker. Some continuations
with r, c/g, l or int give small positive pulses. Transliteration shares
these spelling rules across scripts; no general seating meaning is inferred.
Only the last token is remembered, resetting at document boundaries.
"""
import re
from functools import lru_cache
from anyascii import anyascii

READS = ()

@lru_cache(maxsize=8192)
def spelling(text):
    return anyascii(text).lower()


def predict(previous, text):
    p, s = spelling(previous), spelling(text)
    word = s.lstrip(' _-')
    value = -0.003
    if word == 'sat':
        value += -5.00
    elif re.fullmatch(r'sit(?:s|ting)?', word):
        value += -3.88
    elif word.startswith('sat') and not word.startswith('satis'):
        value += -0.94

    # Continuations must touch the preceding s, with no intervening space.
    if p.endswith('s') and s and s[0].isalpha():
        if s.startswith('at') and not s.startswith('ation'):
            if s == 'at':
                value += -6.07
            elif s.startswith(('att', 'atz', 'ats', 'ath')):
                value += -3.86
            else:
                value += -1.61
            if text.isupper():
                value += -4.81
        elif s == 'it':
            value += -1.72
        elif s.startswith(('itt', 'itz')):
            value += -4.98
        elif s.startswith('it'):
            value += -0.24
        elif s.startswith('et'):
            value += -1.07
        elif s.startswith('ot'):
            value += -0.37
        elif s.startswith('t'):
            value += -0.26
        elif re.match(r'(?:a(?:i)?r|ir)', s):
            value += 0.27
        elif s.startswith(('ic', 'ig')):
            value += 0.22
        elif s in ('ol', 'oll'):
            value += 0.85
        elif s == 'int':
            value += 0.31

    # The s and vowel can instead be on the previous side of the split.
    if re.search(r's[aeiouy]+$', p) and re.match(r'[aeiouy]*(?:t|ct)', s):
        value += -0.33
    if re.search(r's[ai]t$', p) and s.startswith(('t', 'z')):
        value += -3.63
    return value


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == document else ''
    text = prefix.token_strings[-1]
    return (document, text), float(predict(previous, text))

"""Predict a lexical signal for 'on/upon' and common translations.

Dependence, attention and influence constructions weaken the negative signal;
publication, sharing and sitting/standing constructions strengthen it. 'And
so on' reverses it. Word frequencies in the recent phrase help distinguish
languages and ambiguous short words, including French 'on' (a pronoun).
Unrecognized tokens get zero. Only a short text tail is carried between steps;
it is cleared at document boundaries. Smaller background activity is omitted.
"""
import re
import wordnet
from wordfreq import zipf_frequency

READS = ()

PREPOSITIONS = {
    'on': -2.95, 'upon': -3.9, 'onto': -1.0,
    'auf': -1.6, 'sur': -2.75, 'på': -3.85,
    'на': -1.0, 'على': -2.6, 'sobre': -0.25, 'em': -0.25,
}
DEPENDENCE = {'base', 'basis', 'depend', 'dependent', 'rely', 'reliant',
              'reliance', 'dependence'}
ATTENTION = {'focus', 'concentrate', 'emphasis', 'effect', 'impact'}
INFLUENCE = {'point', 'pressure', 'stress', 'influence', 'attention'}
SWITCHING = {'turn', 'switch', 'click', 'put', 'go'}
PUBLICATION = {'publish', 'post', 'release', 'air', 'list', 'file', 'open',
               'close', 'appear', 'write', 'read'}
POSTURE = {'sit', 'stand'}
PARTICLES = {'up', 'down', 'out', 'back', 'away'}

def language_hint(tail, languages):
    """Which language has the most familiar words in the recent phrase?"""
    words = re.findall(r'[^\W\d_]+', tail.lower())[-12:]
    return max(languages, key=lambda lang:
               sum(zipf_frequency(w, lang) for w in words))


EFFECT_PHRASE = re.compile(
    r'\b(effects?|impacts?|influences?)\b((?!\bon\b)[^,;:.!?]){0,65}$', re.I)



def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = carry[1] if carry and carry[0] == doc else ''
    s = prefix.token_strings[-1]
    w = s.strip()
    lower = w.lower()
    boundary = s[:1].isspace() or not tail or not tail[-1:].isalnum()
    value = 0.0
    if lower in PREPOSITIONS and boundary:
        value = PREPOSITIONS[lower]
        if lower == 'on':
            if w == 'On':
                value = -2.2
            elif w == 'ON':
                value = -2.5
            elif s == 'on' and tail[-1:] in ('\n', '('):
                value = -3.9
        elif lower == 'upon' and w[:1].isupper():
            value = -4.0
        elif lower == 'sur' and w[:1].isupper():
            value = -0.7 if s[:1].isspace() else -1.2
        elif lower == 'на' and w[:1].isupper():
            value = -1.6
    elif lower in ('-on', '_on'):
        value = -3.0 if lower == '-on' else -2.2
    elif w == 'On':  # camel-case suffix: createdOn, clickOn, etc.
        value = -1.6
    elif lower in ('na', 'op', 'pe', 'su', 'sul', 'en') and boundary:
        if lower == 'na' and not w.isupper():
            lang = language_hint(tail, ('en', 'pt', 'pl', 'cs', 'sk', 'sh'))
            value = -1.05 if lang == 'pt' else -2.5 if lang != 'en' else 0.0
        elif lower == 'op':
            lang = language_hint(tail, ('en', 'nl', 'da'))
            value = -3.9 if lang == 'nl' else -1.0 if lang == 'da' else 0.0
        elif lower == 'pe':
            lang = language_hint(tail, ('en', 'ro', 'fr', 'es', 'tr', 'id'))
            value = -2.9 if lang == 'ro' else 0.0
        elif lower in ('su', 'sul'):
            lang = language_hint(tail, ('en', 'it', 'es', 'fr'))
            value = -1.45 if lang == 'it' else 0.0
        elif lower == 'en':
            lang = language_hint(tail, ('en', 'es', 'fr', 'nl', 'sv', 'tr'))
            value = -0.65 if lang == 'es' else -0.05
    # The preceding governor determines which construction this is.
    if lower in ('on', 'upon') and value:
        match = re.search(r'([A-Za-z]+)\s*$', tail)
        prev = match.group(1).lower() if match else ''
        forms = set(wordnet.base_forms(prev)) | {prev}
        if forms & {'void', 'def', 'function'}:
            value = 0.0
        elif forms & DEPENDENCE:
            value = -0.95
        elif forms & ATTENTION:
            value = -0.6
        elif forms & INFLUENCE:
            value = -1.4
        elif forms & SWITCHING:
            value = -1.65
        elif forms & {'share', 'vote'}:
            value = -5.7
        elif forms & {'play'}:
            value = -4.9
        elif forms & PUBLICATION:
            value = -4.15
        elif forms & POSTURE:
            value = -4.5
        elif prev in PARTICLES:
            value = -3.7
        elif prev == 'and' and lower == 'on':
            value = -2.1
        elif prev == 'so':
            value = 0.85 if re.search(r'\band\s+so\s*$', tail, re.I) else -1.4
        if lower == 'on':
            # Also recognize 'the effect of X on', not just adjacent 'effect on'.
            if not forms & ATTENTION and EFFECT_PHRASE.search(tail):
                value = -1.05
            if not prev and tail.rstrip().endswith((',', ';')):
                value = -2.1
            if language_hint(tail, ('en', 'fr', 'fi')) != 'en':
                value = 0.1  # French pronoun; Finnish copula.
        if lower == 'upon' and forms & (DEPENDENCE | ATTENTION | INFLUENCE):
            value = -1.7
        if not tail:
            value = -1.1 if w == 'on' else 0.3 if s == 'On' else value
    return (doc, (tail + s)[-180:]), value

"""Approximate two lexical signals, not a single semantic category.

Negative: 'while/whilst', strongest in lowercase prose, weaker after
punctuation or connectives, in 'a while', and beside line indentation.
Positive: short 'lan/land/lane' spelling pieces, including l + an across
tokens, some transliterated forms, and Chinese orchid/blue characters.
The constants are training averages. Other tokens receive zero. Only the
previous token is remembered, and that memory resets between documents.
"""
import regex as re
from anyascii import anyascii
from functools import lru_cache

READS = ()


@lru_cache(maxsize=65536)
def activation(token, previous):
    s = token.strip()
    low = s.lower()
    prev = previous.strip().lower()
    if low in {'while', 'whilst', 'awhile'}:
        if low == 'awhile':
            return -1.4
        if s[0].isupper() and not s.isupper():
            return -1.1 if token[0].isspace() else -1.92
        if previous and (previous.isspace() and len(previous) > 1
                         or previous.endswith(('\n', '\r', '\t'))):
            return -0.29
        if prev in {'a', 'quite'}:
            return -1.4
        if prev in {'and', 'but', 'so', 'that', 'even', 'although',
                    'then', 'or', 'only', 'yet'}:
            return -1.95
        if previous.rstrip().endswith((',', ';', ':')):
            return -2.69
        return -4.66

    if s in {'兰', '蘭'}:  # orchid; also used in transcribed names
        return 6.0
    if s in {'蓝', '藍'}:  # blue
        return 2.27
    if s in {'ラン', 'لندا'}:  # Japanese ran and Arabic -land
        return 3.5
    if re.search(r'[\p{Script=Cyrillic}\p{Script=Hangul}]', s):
        low = anyascii(s).lower()
        if low in {'lan', 'land', 'lands'}:
            return 3.5

    if 'lan' in low:
        if low in {'lan', 'land', 'lands', 'lane', 'lanes'}:
            if s.isupper():
                return 4.48
            if token[0].isspace():
                return 2.9 if s[0].isupper() else 1.21
            return 4.33
        # Vowel-initial pieces such as elan, olan, and olland.
        if re.fullmatch(r'[aeiouy]+l?lan(?:d|ds|e|es|s)?', low):
            if not token[0].isspace():
                return 3.55
        if re.fullmatch(r'[a-z]*lan(?:d|ds|e|es|s|der|ders)?', low):
            if not token[0].isspace():
                return 0.52
            return 0.49 if low.endswith('lan') else 0.2
        return 0.0

    # An l at the end of the previous piece can begin the same syllable.
    if not token[:1].isspace() and anyascii(previous).endswith(('l', 'L')):
        if re.fullmatch(r'ands?', low):
            return 7.5
        if re.fullmatch(r'and[aeiou]s?', low):
            return 4.31
        if re.fullmatch(r'an[aeiouy]?s?', low):
            return 4.0
        if re.fullmatch(r'an[ctz]h?', low):
            return 2.45
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = '' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    return (doc, token), activation(token, previous)

"""A whole-word 'on' detector, modulated by familiar collocations.

The response is large for ordinary 'on'/'upon' and close translations, but
small after words selecting an on-complement ('based', 'depends', 'focus',
etc.). It is reduced after common particle-taking verbs; 'so on' is negative.
Word endings are excluded. Side rules cover headings and 'morning of' dates.
"""
import re
from functools import cache
import wordnet

READS = ()

SELECT_ON = {
    'base', 'depend', 'dependent', 'dependence', 'rely', 'reliant',
    'reliance', 'focus', 'impact', 'effect', 'concentrate', 'emphasis',
}
PARTICLE_VERBS = {
    'go', 'keep', 'carry', 'hold', 'turn', 'switch', 'click', 'point',
    'press', 'move', 'come', 'get', 'take', 'put',
}
# Translations of 'on', and the related spatial prepositions onto/along.
PREPOSITIONS = {
    'sur': 1.34, 'auf': 0.96, 'на': 1.01, 'na': 1.10,
    'på': 1.81, 'على': 1.24, 'op': 0.60,
    'onto': 0.54, 'along': 0.41,
}
# Case can distinguish a preposition from a name or abbreviation.
CASE_VARIANTS = {
    'На': 1.48, 'Na': 0.50, 'Sur': 0.48,
    'NA': 0.0, 'НА': 0.05, 'SUR': 0.20, 'OP': 0.25,
}


@cache
def base_forms(word):
    return set(wordnet.base_forms(word)) | {word}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    previous = '' if first else carry[1]
    raw = prefix.token_strings[-1]
    spelling = raw.strip()
    word = spelling.lower()
    value = 0.0
    boundary = (not previous or raw[:1].isspace()
                or not (previous[-1].isalnum() or previous[-1] == '_'))
    match = re.search(r'([^\W\d_]+)\s*$', previous)
    before = match.group(1).lower() if match else ''

    if raw == '#':
        value = (-0.48 if first else
                 0.34 if previous.endswith('\n\n') else 0.0)
    elif raw == ' of' and before in {
        'morning', 'afternoon', 'evening', 'night', 'eve',
    }:
        value = 0.68
    elif word.lstrip('-_') in {'on', 'upon'}:
        word = word.lstrip('-_')
        if boundary or spelling.startswith(('-', '_')):
            forms = base_forms(before)
            value = 1.86 if word == 'upon' else 1.52
            if word == 'on' and spelling != spelling.lower():
                value = 1.16 if spelling.title() == spelling else 0.95
            if forms & SELECT_ON:
                value = 0.45 if word == 'upon' else 0.16
            elif word == 'on':
                if before == 'so':
                    value = -0.46
                elif forms & PARTICLE_VERBS:
                    value = 0.94
                elif previous.endswith(','):
                    value = 1.0
            if first and word == 'on':
                value = -0.30 if spelling == 'On' else 0.50
    elif boundary and word in PREPOSITIONS:
        value = CASE_VARIANTS.get(spelling, PREPOSITIONS[word])

    return (doc, (previous + raw)[-100:]), value

