"""layers.1.mlp.down_proj:3306 -- an "on" detector.

What it does: the component fires on the preposition "on" as a whole word, and on its
equivalents in other languages (upon, sur, auf, на, på, na, op, onto, along). It does
not fire on "on" inside a longer word (iPhone, Avitone). Activation is about 1.2 on
such a word. It is largest after a past participle ("posted on", "listed on",
"played on"), and near zero where "on" is the fixed complement of a dependence word
("depends on", "based on", "focus on", "rely on", "and so on"). Everywhere else it is
near zero.
"""
READS = ()

# Typical activation on each "on"-type preposition, as a whole word.
ON_WORDS = {
    "on": 1.2, "upon": 1.6, "sur": 1.4, "auf": 0.9, "на": 0.9, "på": 1.9,
    "على": 1.4, "na": 0.6, "onto": 0.4, "op": 0.2, "along": 0.4,
}

# Words after which "on" is a fixed, abstract complement (depends on, based on...).
DEPENDENCE = {
    "depend", "depends", "depending", "depended", "dependent", "dependence",
    "rely", "relies", "relied", "relying", "reliance", "based", "focus",
    "focused", "focuses", "focusing", "so", "effect", "effects", "emphasis",
    "impact", "impacts", "concentrate", "heavily", "mainly", "chiefly",
}


def is_whole_word(prefix):
    """True if the newest token starts a word: it has a leading space, or the
    token before it does not end in a letter or digit."""
    token = prefix.token_strings[-1]
    if token[:1].isspace() or len(prefix.token_ids) == 1:
        return True
    if prefix.document_ids[-2] != prefix.document_ids[-1]:
        return True
    return not prefix.token_strings[-2][-1:].isalnum()


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    if word not in ON_WORDS or not is_whole_word(prefix):
        return None, 0.0
    if len(prefix.token_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]:
        before = prefix.token_strings[-2].strip().lower()
        if before in DEPENDENCE:
            return None, 0.0
        if before.endswith("ed"):
            return None, 1.9
    return None, ON_WORDS[word]

