"""A document-start pulse, estimated from readable token classes.

Most tokens after the first are nearly zero. The exceptions modeled here are
positive deliberative phrases (let me/us, let's, I/we will or shall), and
initial runs containing just one repeated token. The onset estimate is deliberately coarse:
case, spacing, articles, punctuation, and a few grammatical classes matter.
"""
import unicodedata

READS = ()


def onset(s):
    t = s.strip()
    word = t.lower()
    spaced = s.startswith(' ')
    if s.startswith('<|'):
        return -6.75
    if not t:
        if s == '\r':
            return -14.0
        if s == '\t':
            return -5.3
        if '\n' in s:
            return -1.0
        return -1.7 if len(s) == 1 else -2.8
    if t.isascii() and t.isdigit():
        return 1.5 if t == '1' else -0.5 - 0.2 * min(int(t), 10)
    # Articles have an unusually strong dependence on case and spacing.
    if word == 'an':
        return -14.6 if spaced else (-19.2 if t == 'An' else -9.1)
    if word == 'a':
        return -2.4 if spaced else 0.9
    if word == 'the':
        return -3.7 if s == ' the' else (-4.6 if s == 'The' else -5.8)
    if t.startswith('#'):
        return -0.5
    if t.startswith('@'):
        return -32.0 if t == '@' else -21.0
    if t.startswith('//') and '\n' in s:
        return -27.0
    if t.startswith(';'):
        return -12.0 if '\n' in s else -6.8
    if t.startswith('__'):
        return -12.6
    if t and set(t) <= {'·'}:
        return -13.0
    if t and set(t) <= {'^'}:
        return -19.0 if len(t) > 1 else -6.8
    if t == '_\\':
        return -23.0
    if t in ('\\n', '\\t'):
        return 2.5
    if len(t) == 1:
        if unicodedata.category(t) == 'Sc':
            return -8.3 if spaced else -16.0
        if t == '*':
            return -9.0
        if t in '-=|/:':
            return -0.9
        if t.isascii() and t.isalpha():
            return -3.5 if spaced else -0.9
        if not t.isalnum():
            return -2.7
    if word in ('in', 'on', 'at', 'from', 'into'):
        return -2.8
    if word in ('to', 'with', 'by', 'as', 'of'):
        return -5.0
    if word in ('import', 'using'):
        return -8.3
    if not spaced and word in (
        'what', 'how', 'why', 'where', 'when', 'which'
    ):
        return -8.0
    if t.isascii() and t.isupper():
        return -2.5
    if not t.isascii():
        return -3.0
    if t[0].isupper():
        return -5.3
    return -3.7


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    s = prefix.token_strings[-1]
    token = prefix.token_bytes[-1]
    if carry is None or carry[0] != doc:
        return (doc, s, token), onset(s)
    previous_text = carry[1].strip()
    previous = previous_text.lower()
    current = s.strip().lower()
    first_run = carry[2]
    if token != first_run:
        first_run = None
    value = 0.0
    if first_run is not None:
        value = onset(s)
    elif previous == 'let':
        if current == 'me':
            value = 1.2 if previous_text[0].isupper() else 1.0
        elif current in ('us', "'s", '’s'):
            value = 0.7 if previous_text[0].isupper() else 0.55
    elif previous in ('i', 'we'):
        if current == 'shall':
            value = 1.0
        elif current in ('will', "'ll", '’ll'):
            value = 0.7 if previous_text[0].isupper() else 0.5
    return (doc, s, first_run), value

