"""Approximate a signed M--N / M--Q letter-pair detector.

A split-off N after M is positive; Q after M is negative. Short MN/MQ
fragments also respond. Only Latin, Cyrillic and Greek letters are
transliterated. MNIST, Minnesota and manganese are associated with MN/Mn. Doubled middle dots
have a separate negative response. A little signal continues into a suffix.
The baseline is near zero, and slightly negative at document starts.
"""
from functools import lru_cache
import unicodedata
from anyascii import anyascii

READS = ()


@lru_cache(maxsize=16384)
def letters(text):
    result = []
    for ch in text:
        name = unicodedata.name(ch, '')
        if any(script in name for script in ('LATIN', 'CYRILLIC', 'GREEK')):
            ch = anyascii(ch)
        result.append(ch)
    return ''.join(result).lower()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    fresh = carry is None or carry[0] != doc
    previous, last_value = ('', 0.0) if fresh else carry[1:]
    raw = prefix.token_strings[-1]
    token = letters(raw)
    core = token.strip()
    value = -0.16 if fresh else 0.004

    if previous.endswith('m') and token.startswith('n'):
        if len(token) == 1:
            value = 4.5 if previous.strip() == 'm' else 8.2
        else:
            value = 5.2 if len(token) <= 3 else 2.8
            if len(token) <= 3 and token.count('n') > 1:
                value = 9.5
    elif previous.endswith('m') and token.startswith('q'):
        value = -10.5 if len(token) == 1 else -2.5
    elif core == 'mn':
        value = 4.6 if raw[:1].isspace() or raw.isupper() else 3.0
    elif core == 'mq':
        value = -7.5
    elif 'mn' in core and len(core) <= 4:
        value = 3.5 if len(core) == 3 else 1.6
    elif (previous + token).endswith(('minnesota', 'manganese')):
        value = 3.7
    elif previous.strip() == 'mn' and token == 'ist':
        value = 6.5
    elif previous.strip() == 'mn' and token[:1].isalpha():
        value = 2.5
    elif 'm' in previous and token.startswith('n'):
        value = 0.8 if len(token) <= 2 else 0.2
    elif token[:1].isalpha() and abs(last_value) > 1.0:
        value = 0.2 * last_value

    if raw == '··':
        value = -1.8
    return (doc, token, value), value

"""Recognize file-type endings, even when tokenization splits the ending.

Programming and configuration suffixes give negative pulses; ordinary text
is near zero. Ambiguous one-letter suffixes need filename/path context.
Hidden configuration files, build-file names, and fenced language labels
are related triggers, as is GitHub's domain ending. A document-opening
'Title:' colon is unusually strong.
"""
import re

READS = ()

# The response differs between familiar families of file types.
SUFFIX = {}
for strength, names in (
    (6.4, 'rs rake'),
    (5.3, 'go cpp'),
    (4.6, 'py cc rb lua swift pm'),
    (4.1, 'js ts java jar json yaml toml'),
    (4.5, 'yml sh conf cfg ini rst egg tmp'),
    (7.0, 'whl'),
    (8.5, 'dta'),
    (5.5, 'dat mjs'),
    (3.5, 'txt vue xml php csv zip gz tgz tar sql db so mk'),
    (3.2, 'md pdf'),
    (2.8, 'spec lib gif'),
    (2.0, 'html htm css png svg dll lock'),
    (1.4, 'jpg jpeg test sum hpp'),
    (5.0, 'tsx jsx ipynb'),
):
    SUFFIX.update((name, -strength) for name in names.split())

HIDDEN = ('gitignore', 'gitattributes', 'gitmodules', 'travis',
          'npmrc', 'bashrc', 'bash_profile', 'env')
COMMON_C_HEADERS = set(('stdio stdlib stdint stddef string math time '
                        'assert ctype errno limits float signal stdarg '
                        'stdbool wchar windows conio').split())
LANGUAGES = {'python', 'javascript', 'typescript', 'rust', 'bash',
             'shell', 'cpp', 'csharp', 'java', 'go', 'ruby'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        count, tail, last = 0, '', ''
    else:
        _, count, tail, last = carry
    s = prefix.token_strings[-1]
    value = 0.0
    if s == ':' and last == 'Title' and count == 1:
        value = -13.86
    elif s.startswith('.'):
        ext = s[1:]
        value = SUFFIX.get(ext, 0.0)
        name = re.search(r'[\w./\\-]*\Z', tail)[0]
        quoted = len(name) < len(tail) and tail[-len(name)-1] in "'\"`<"
        filename = '/' in name or '\\' in name or quoted
        hint = 'file' in tail.lower() or '#include' in tail
        if ext in {'c', 'h', 'd', 'r', 'in', 'list', 'properties', 'sql',
                   'a', 'inf', 'ip', 'm'}:
            value = -4.0 if filename or hint else -0.1
            if ext in {'c', 'a', 'inf', 'ip', 'm', 'r'} and (filename or hint):
                value = -6.3
