                value -= 1.17 if w.startswith('qu') else 1.73
        if len(w) <= 4:
            if w.startswith(('x', 'ξ')):
                value -= 3.11 if w == 'x' else 1.54
                if w == 'ξ':
                    value -= 4.88
            if w.startswith('ks') or w[:1] in ('キ', 'ク'):
                value -= 2.67
            elif w[:1] in ('k', 'κ', 'к'):
                value -= 0.20
            if w.startswith('κ'):
                value -= 1.08
        if w.startswith('π'):
            value -= 1.36
    if continuation and tail.endswith(('ek', 'ек', 'эк')):
        if w.startswith(('s', 'с')):
            value -= 1.22
    if continuation and tail.endswith('equ'):
        if w in ('ate', 'ates', 'ating'):
            value -= 6.03
        elif w == 'ity':
            value -= 6.0
        elif w.startswith('it'):
            value -= 2.18
        elif w.startswith('il'):
            value -= 0.53
        else:
            value -= 0.19
    if continuation and tail.endswith('emp') and w.startswith('ower'):
        value -= 3.82
    if continuation and tail.endswith('end') and w.startswith('ow'):
        value -= 1.08
    if continuation and tail.endswith('eff'):
        if w.startswith('ector'):
            value += 4.18
        elif len(w) <= 4:
            value += 0.19
    if continuation and tail.endswith(('elect', 'effect')):
        if w.startswith('or'):
            value += 0.62

    # Small background spelling and beginning-of-document offsets.
    if w == 'quality':
        value += 0.28
    if w in ('power', 'powers', 'powerful'):
        value += 0.19
    if w in ('x', '(x', '.x'):
        value += 0.10
    if w and not w.strip('=') and len(w) >= 2:
        value -= 0.10
    if new or previous == '<|endoftext|>':
        if token.isalpha():
            value += 0.21
        elif token.startswith(' ') and token.strip().isalpha():
            value += 0.08
        elif not token.strip().isalpha():
            value += 0.04
    return (doc, token), float(value)

"""A spelling-based approximation to a negative T/tau response.

Penalties mark T-initial (not TH-initial) tokens, continued short
T-initial words, and nearby repetitions of T. Common English T-initial
spellings get a small discount. Greek tau prefixes and document starts
have separate corrections. Keep only the trailing word and document ID;
individual token-specific activation differences remain unexplained.
"""
from functools import lru_cache
import unicodedata
import regex
from anyascii import anyascii
from wordfreq import zipf_frequency

READS = ()

@lru_cache(maxsize=20000)
def spelling(s):
    text = anyascii(s).lower()
    word = text.strip(" \n\r\t._/-(,'\"")
    starts_t = word.startswith("t") and not word.startswith("th")
    return text, word, starts_t


def close_ts(word):
    places = [i for i, ch in enumerate(word) if ch == "t"]
    return any(b - a <= 4 for a, b in zip(places, places[1:]))


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    oldword = "" if first else carry[1]
    s = prefix.token_strings[-1]
    text, word, starts_t = spelling(s)
    old = anyascii(oldword).lower()
    continues = bool(text and text[0].isalpha())
    old_t = old.startswith("t") and not old.startswith("th")

    value = 0.0008
    if first:
        value += 0.2353
        if "t" in word:
            value -= 0.1857
        if word.startswith("t") and s.isupper() and len(word) <= 3:
            value -= 0.7741
    if starts_t:
        value -= 0.0311
        if zipf_frequency(word, "en") >= 5:
            value += 0.0159
    if close_ts(word) and not word.startswith("th"):
        value -= 0.0109
    if continues:
        if old_t:
            value -= 0.0432
            if len(old) <= 3:
                value -= 0.0661
        if len(old) <= 7 and close_ts(old):
            value -= 0.0584
        if "t" in old and "t" in text:
            distance = len(old) - old.rfind("t") + text.find("t")
            if distance <= 5:
                value -= 0.0679

    # Greek tau-initial prefixes one or two letters long.
    greek = "".join(ch for ch in unicodedata.normalize("NFD", oldword)
                    if not unicodedata.combining(ch))
    if s and regex.match(r"\p{Script=Greek}", s[0]):
        if greek == "τ":
            value -= 0.1138
        if len(greek) == 2 and greek.startswith("τ"):
            value -= 0.4602

    tail = regex.search(r"[\p{L}\p{M}]+$", s.lower())
    if tail is None:
        newword = ""
    elif tail.start() == 0:
        newword = (oldword + s.lower())[-40:]
    else:
        newword = tail.group()
    return (doc, newword), float(value)

"""A spelling-and-local-phrase approximation, with no token-ID lookup.

The main negative cue is the `prec` spelling in appreciation and deprecation
words, including pieces split between tokens. Other `prec` spellings are
weaker. A few immediate English complements, Cyrillic pre-/pri- syllables,
and middle-dot punctuation supply smaller corrections. Everything else gets
a nearly zero baseline. Word state resets at document and camel-case boundaries.
"""
import re
import unicodedata

READS = ()


def response(word, old, token):
    split = token.isalpha() and bool(old) and word != token
    if re.search(r'apprec|aprec|apprez', word):
        if token in ('rec', 'reci', 'zz'):
            return -13.34
        if re.search(r'appreciabl[ey]?$', word):
            return -2.21
        if word.endswith('appreciated') and not split:
            return -6.06
        return -7.78
    if 'deprec' in word:
        if token in ('rec', 'prec', 'preci'):
            return -8.54
        if split and old.endswith(('rec', 'preci')):
            return -6.42
        return -4.16
    if 'prec' in word or 'grec' in word:
        if word.endswith(('prec', 'preci', 'preca', 'grec')):
            return -2.53
        if split and old.endswith(('prec', 'preci', 'grec', 'preco')):
            return -1.44
        return -0.17
    if re.search(r'пр(?:ис|ес|есс|еб|ем|ез|еп)$', word):
        return 2.51
    if token == 'from' and old in ('benefit', 'benefits', 'benefited', 'apart'):
        return -2.78
    if token in ('of', 'for') and re.search(
            r'appreci|depreci|gratitude|grateful|thankful|preference', old):
        return -3.29
    if token == 'it' and old in (
            'love', 'loves', 'loved', 'like', 'liked', 'likes',
            'prefer', 'preferred', 'worth', 'appreciate'):
        return -1.30
    if token == 'like' and old == 'more':
        return 2.22
    if token == 'like' and old in ('just', 'exactly'):
        return 1.20
    if re.fullmatch(r'grat(?:eful|itude)', word) or token in ('感谢', '感謝'):
        return -1.01
    if token and set(token) == {'·'}:
        return -0.84
    return -0.002


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    old = carry[1] if carry is not None and carry[0] == doc else ''
    source = prefix.token_strings[-1]
    # Treat a new TitleCase segment as a new word in code identifiers.
    if source[:1].isupper() and source[1:2].islower():
        old = ''
    raw = ''.join(c for c in unicodedata.normalize('NFD', source.lower())
                  if unicodedata.category(c) != 'Mn')
    match = re.search(r'[^\W\d_]+$', old + raw)
    word = match.group() if match else ''
    value = response(word, old, raw.strip())
    return (doc, word[-48:]), value

"""Approximate a response to fragmented accented syllables in Iberian text.

Completed-word frequencies estimate the surrounding language. Short tokens
isolating an accented vowel, and consonant-only tokens immediately after one,
receive negative values. A prefix already common as a word weakens the response;
longer consonant continuations strengthen it. Most other tokens stay near zero.
Separate rules reproduce initial Title: labels and repeated middle dots.
"""
import codecs
import math
import re
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()
LANGUAGES = ('es', 'pt', 'ca', 'fr', 'cs', 'hu', 'pl', 'it', 'de', 'en')
ACCENTS = set('áéíóúàèìòùâêîôû')
VOWELS = set('aeiouyáéíóúàèìòùâêîôûäëïöüãõ')


@lru_cache(maxsize=100000)
def language_evidence(word):
    if not word.isalpha() or not all(ord(c) < 600 for c in word):
        return (0.,) * len(LANGUAGES)
    frequencies = [max(1., zipf_frequency(word, lang)) for lang in LANGUAGES]
    best = max(frequencies)
    return tuple(f - best for f in frequencies)


@lru_cache(maxsize=100000)
def completed_word_frequency(word):
    return min(1., max(zipf_frequency(word, lang)
                       for lang in LANGUAGES[:3]) / 6.)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', '', (0.,) * len(LANGUAGES), 0, b'')
    _, word, previous, scores, position, pending = carry
    raw = pending + prefix.token_bytes[-1]
    token, consumed = codecs.utf_8_decode(raw, 'ignore', False)
    pending = raw[consumed:]

    # Accumulate a word, updating language evidence only once it has ended.
    for piece in re.findall(r'[^\W\d_]+|[\W\d_]+', token):
        if piece[0].isalpha():
            word = (word + piece.lower())[-50:]
        else:
            if word:
                evidence = language_evidence(word)
                scores = tuple(.97 * a + b for a, b in zip(scores, evidence))
            word = ''
    maximum = max(scores)
    probabilities = [math.exp((v - maximum) / 4.) for v in scores]
    iberian = sum(probabilities[:3]) / sum(probabilities)

    s = token.strip().lower()
    short = s.isalpha() and len(s) <= 5 and all(ord(c) < 600 for c in s)
    consonants = short and not any(c in VOWELS for c in s)
    isolated = short and not any(c in VOWELS - ACCENTS for c in s)
    accent = isolated and any(c in ACCENTS for c in s)
    after_accent = consonants and previous and previous[-1].lower() in ACCENTS
    value = -.00056 - .093 * (position == 0)
    if consonants:
        value -= .293 * iberian
    if accent or after_accent:
        frequency = completed_word_frequency(word)
        last_accent = max((i for i, c in enumerate(word) if c in ACCENTS),
                          default=-1)
        tail = min(3, len(word) - last_accent - 1) if last_accent >= 0 else 0
        if accent:
            value += iberian * (-2.755 + 1.854 * frequency + .420 * tail)
        if after_accent:
            value += iberian * (-1.610 + .634 * frequency - 1.267 * tail)
    if token.strip() == ':' and previous == 'Title' and position == 1:
        value = 5.109
    if s and set(s) == {'·'} and previous and set(previous) == {'·'}:
        value = .649
    previous = token.strip() if token else previous
    return (doc, word, previous, scores, position + 1, pending), float(value)

"""Recognize a few strong document-opening signals.

Title headers peak on their colon. Opening code declarations/imports and the
word 'test' give a positive signal, but 'package' gives a negative one.
A leading empty quoted string followed by a comma also responds, as does
a document separator at the start.
All other first tokens get a small offset; later ordinary text is near zero.
"""

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        position = 0
        first = token
    else:
        position = carry[1] + 1
        first = carry[2]

    value = -0.001
    if position == 0:
        value = 0.24
        if token == 'Title':
            value = 1.14
        elif token == '<|endoftext|>':
            value = 1.97
        elif token in {'def', 'int'}:
            value = 2.28
        elif token == 'void':
            value = 2.65
        elif token in {'class', 'function'}:
            value = 0.8
        elif token == 'import':
            value = 1.03
        elif token == 'package':
            value = -0.78
        elif token.strip().lower() == 'test':
            value = 2.22 if token.startswith(' ') else 1.63
        elif token.strip() == '"",':
            value = 2.21
        elif token.isdecimal():
            value = 0.1
    elif position == 1 and first == 'Title' and token == ':':
        value = 3.217
    return (doc, position, first), value

programs.haiku:
"""Layer-1 MLP down_proj, component 3326: a document-start detector.

It reads the first token of each document (the token right after <|endoftext|>,
where the model has no earlier context). That first token is mildly positive
(about 0.25) and it spikes on a few header and code-opening tokens:
  * the ':' of a "Title:" header that opens a document (about 3.2);
  * a code file's first word 'def', 'int', 'void' (about 2.3 to 2.6), or 'test' (about 1.8);
  * a run of middle-dot filler '··' (about 2.1).
'package' (a Java/Go declaration keyword) is mildly negative (about -0.35).
Everywhere else it is near 0.
"""

READS = ()

DOC_START_BASE = 0.25
CODE_FIRST_WORD = {"def": 2.3, "int": 2.3, "void": 2.6, "test": 1.8, "tests": 1.8}
DOT_FILLER = "··"
TITLE_COLON = 3.2
PACKAGE = -0.35


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tok = prefix.token_strings[-1]
    if carry is None or carry[2] != doc:
        pos, prev = 0, None          # first token of a new document
    else:
        pos, prev = carry[0] + 1, carry[1]
    if tok == DOT_FILLER:
        value = 2.1
    elif pos == 0:
        value = CODE_FIRST_WORD.get(tok.strip(), DOC_START_BASE)
    elif pos == 1 and prev == "Title" and tok == ":":
        value = TITLE_COLON
    elif tok == "package":
        value = PACKAGE
    else:
        value = 0.0
    return (pos, tok, doc), value

programs.sol:
"""Approximate a detector for international-looking word fragments.

A word is tracked across token boundaries. Its accent-stripped, roughly
phonetic spelling is compared with prefixes shared by common English and
Romance words. Longer shared stems, particularly later pieces of Cyrillic
words, get larger positive predictions. Recent frequent words provide a
rough language estimate; English and Romance contexts get smaller values.
Later Cyrillic pieces also retain a small generic continuation response.
All-capital words and mixed-case identifiers are excluded. The rules are
a coarse approximation: many lexical and inflection-specific effects are
left unexplained.
"""
import re
import unicodedata
from functools import lru_cache
from anyascii import anyascii
from wordfreq import top_n_list

READS = ()
LANGUAGES = ('en', 'de', 'fr', 'es', 'it', 'pt', 'pl', 'ru', 'tr', 'id',
             'nl', 'fi', 'hu', 'cs', 'sk', 'uk', 'bg', 'sv', 'da', 'nb', 'ro')
ROMANCE = {'fr', 'es', 'it', 'pt', 'ro'}
FREQUENT_WORDS = [set(top_n_list(lang, 70)) for lang in LANGUAGES]

@lru_cache(maxsize=100000)
def spelling(word):
    s = anyascii(word).lower().replace('ph', 'f').replace('th', 't')
    s = s.replace('ts', 's').replace('sh', 's').replace('ch', 'k')
    s = s.replace('iu', 'u').replace('ia', 'a').replace('x', 'ks')
    s = re.sub(r'ti(?=[oa])', 'si', s)
    s = re.sub(r'c(?=[eiy])', 's', s).replace('kh', 'k')
    s = s.translate(str.maketrans({'c':'k', 'q':'k', 'w':'v', 'y':'i', 'z':'s'}))
    s = s.replace('iu', 'u').replace('ia', 'a')
    return re.sub(r'(.)\1+', r'\1', s)


def prefixes(language):
    result = set()
    for word in top_n_list(language, 30000):
        if word.isalpha():
            w = spelling(word)
            if len(w) >= 5:
                result.update(w[:i] for i in range(4, len(w) + 1))
    return result

ENGLISH = prefixes('en')
SHARED = ENGLISH & (prefixes('fr') | prefixes('es') | prefixes('it'))

@lru_cache(maxsize=100000)
def votes_for(word):
    return tuple(float(word.lower() in words) for words in FREQUENT_WORDS)

@lru_cache(maxsize=200000)
def stems(word):
    if not all(ord(c) < 128 or 'LATIN' in unicodedata.name(c, '')
               or 'CYRILLIC' in unicodedata.name(c, '') for c in word):
        return 0, 0, 0
    w = spelling(word)
    n = len(w)
    shared = max((i for i in range(4, n+1) if w[:i] in SHARED), default=0)
    inner = max((i-j for j in range(max(0, n-4))
                 for i in range(j+5, min(n, j+15)+1)
                 if w[j:i] in SHARED), default=0)
    return n, shared, inner


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', 0, [0.0]*len(LANGUAGES))
    _, word, pieces, votes = carry
    text = prefix.token_strings[-1]
    old = word
    continuation = bool(text and text[0].isalpha() and word)
    for chunk in re.findall(r'[^\W\d_]+|[^\w]+|[\d_]+', text):
        if chunk.isalpha():
            word += chunk
        else:
            if word:
                votes = [0.93*v+a for v, a in zip(votes, votes_for(word))]
            word = ''
    pieces = (pieces + 1 if continuation else 1) if word else 0
    carry = (doc, word[-60:], pieces, votes)
    n, root, inner = stems(word)
    language = LANGUAGES[max(range(len(votes)), key=votes.__getitem__)]
    foreign = max(votes[1:]) - votes[0]
    cyrillic = any('CYRILLIC' in unicodedata.name(c, '') for c in word)
    suffix = spelling(word[len(old):] if continuation else word)
    # Leave identifiers and all-capital abbreviations alone.
    if not (word.islower() or word.istitle()):
        return carry, 0.0
    near_whole = root >= max(4, n-3)
    value = 0.0
    if cyrillic:
        if inner >= 6:
            value = 0.55 if pieces <= 2 else 1.10
        elif pieces >= 3:
            value = 0.40 if near_whole else 0.15
        elif root >= 5:
            value = 0.25
    elif language != 'en' and language not in ROMANCE:
        if inner >= 5 and len(suffix) <= 4:
            value = 0.90 if root >= 7 else 0.27
        elif foreign > 2.0:
            value = 0.15 if inner >= 5 else (0.07 if root >= 4 else 0.0)
    elif pieces >= 3 and near_whole:
        value = 0.06
    return carry, value
